func (fmr *firehoseReceiver) validate(r *http.Request) (int, error) {
    // If an access key is configured, enforce its presence and correctness.
    if len(fmr.config.AccessKey) > 0 {
        accessKey := r.Header.Get(headerFirehoseAccessKey)

        // Reject if the header is missing or does not match the expected key.
        if accessKey == "" || accessKey != string(fmr.config.AccessKey) {
            return http.StatusUnauthorized, errInvalidAccessKey
        }
    }

    // Either no key is required, or the supplied key is valid.
    return http.StatusAccepted, nil
}

