func Clean(p string) string {
    // Normalise Windows path separators so that path.Clean can reliably
    // eliminate any traversal components ("../") on all platforms.
    p = strings.ReplaceAll(p, "\\", "/")

    // Remove any NUL bytes that could be used to truncate path processing
    if idx := strings.IndexByte(p, 0); idx != -1 {
        p = p[:idx]
    }

    // Prepend a slash to ensure we always clean relative to the root, then
    // trim the leading and trailing slashes to keep the original behaviour.
    return strings.Trim(path.Clean("/"+p), "/")
}

