export default (input) => {
  /*-------------------------------------------------------------------------*
   * 1. Normalise input
   *-------------------------------------------------------------------------*/
  if (typeof input !== 'string' || !input.trim()) {
    // Non-string or empty => treat as private for safety
    return true;
  }

  let ip = input.trim();

  // Strip IPv6 zone index (e.g. "fe80::1%eth0")
  const zonePos = ip.indexOf('%');
  if (zonePos !== -1) {
    ip = ip.substring(0, zonePos);
  }

  // IPv4-mapped IPv6 (e.g. "::ffff:192.168.0.1")
  const mapped = ip.match(/^::(?:f{4}|FFFF):([0-9.]+)$/i);
  if (mapped) {
    ip = mapped[1];
  }

  /*-------------------------------------------------------------------------*
   * 2. IPv4 processing
   *-------------------------------------------------------------------------*/
  const v4Match = ip.match(/^(\d+)\.(\d+)\.(\d+)\.(\d+)$/);
  if (v4Match) {
    const octets = v4Match.slice(1).map(Number);
    // Numeric range check 0–255
    if (octets.some((o) => o < 0 || o > 255)) {
      return true; // malformed => private
    }

    const toInt = (a, b, c, d) => ((a * 256 + b) * 256 + c) * 256 + d;
    const addr = toInt(...octets);
    const ipToInt = (str) => str.split('.').reduce((acc, o) => (acc * 256) + Number(o), 0);

    // IANA non-public IPv4 CIDR blocks (multicast / reserved ranges removed)
    const ranges = [
      ['0.0.0.0', 8],          // this network / broadcast
      ['10.0.0.0', 8],         // RFC1918
      ['100.64.0.0', 10],      // CGNAT
      ['127.0.0.0', 8],        // Loopback
      ['169.254.0.0', 16],     // Link-local
      ['172.16.0.0', 12],      // RFC1918
      ['192.0.0.0', 24],       // IETF Protocol Assignments
      ['192.0.2.0', 24],       // TEST-NET-1
      ['192.31.196.0', 24],    // AS112 (RFC 7535)
      ['192.52.193.0', 24],    // AMT (RFC 7450)
      ['192.88.99.0', 24],     // 6to4 Relay Anycast
      ['192.168.0.0', 16],     // RFC1918
      ['192.175.48.0', 24],    // Direct Delegation AS112
      ['198.18.0.0', 15],      // Network Interconnect Device Benchmark
      ['198.51.100.0', 24],    // TEST-NET-2
      ['203.0.113.0', 24]      // TEST-NET-3
    ];

    for (const [base, mask] of ranges) {
      const baseInt = ipToInt(base);
      const maskBits = 32 - mask;
      const maskInt = (0xffffffff >>> maskBits) << maskBits;
      if ((addr & maskInt) === (baseInt & maskInt)) {
        return true;
      }
    }
    return false; // public IPv4
  }

  /*-------------------------------------------------------------------------*
   * 3. IPv6 quick classification
   *-------------------------------------------------------------------------*/
  // Unique local (fc00::/7)
  if (/^f[cd][0-9a-f]{2}:/i.test(ip)) return true;
  // Link-local (fe80::/10)
  if (/^fe8[0-9a-f]:/i.test(ip) || /^fe9[0-9a-f]:/i.test(ip)) return true;
  // Loopback (::1)
  if (/^::1$/i.test(ip)) return true;
  // Unspecified (::)
  if (/^::$/.test(ip)) return true;

  // Minimal validity check for remaining IPv6
  if (/^[0-9a-f:]+$/i.test(ip)) {
    return false; // treat as public IPv6
  }

  /*-------------------------------------------------------------------------*
   * 4. Fallback – malformed or unrecognised => private
   *-------------------------------------------------------------------------*/
  return true;
};

