func (c *client) AuthenticateToken(r *http.Request) (*library.User, error) {
	logrus.Trace("Authenticating user via token")

	// Retrieve and sanitize the provided token.
	token := strings.TrimSpace(r.Header.Get("Token"))
	if token == "" {
		return nil, errors.New("no token provided")
	}

	// Prevent potential memory-exhaustion attacks with an unreasonably large header.
	const maxTokenSize = 4096
	if len(token) > maxTokenSize {
		return nil, errors.New("token exceeds maximum allowed size")
	}

	// Primary authentication – validate the token and obtain the username.
	u, err := c.Authorize(token)
	if err != nil {
		return nil, err
	}

	// Secondary authorization – ensure the authenticated user is still active.
	active, err := c.IsUserActive(u)
	if err != nil {
		return nil, err
	}
	if !active {
		return nil, errors.New("user is not authorized")
	}

	// Do NOT return the raw token to avoid unintentional credential leakage.
	return &library.User{
		Name: &u,
	}, nil
}

