// validateRelativePath ensures the provided path is relative and does not
// contain any traversal components that could escape the intended working
// directory. This prevents an attacker from writing files to arbitrary
// locations on the host.
func validateRelativePath(p string) error {
    // Empty path is allowed (defaults to repo root)
    if p == "" {
        return nil
    }

    // Reject absolute paths ("/tmp", "C:\\tmp", etc.)
    if filepath.IsAbs(p) {
        return fmt.Errorf("directory %q must be a relative path", p)
    }

    cleaned := filepath.Clean(p)

    // Reject any path that tries to traverse outside the working directory
    if cleaned == ".." || strings.HasPrefix(cleaned, ".."+string(os.PathSeparator)) {
        return fmt.Errorf("directory %q cannot contain path traversal", p)
    }

    // Disallow Windows drive-letter references such as "C:" – they imply
    // an absolute location outside the intended base path.
    if len(cleaned) >= 2 && cleaned[1] == ':' {
        return fmt.Errorf("directory %q cannot specify drive letter", p)
    }

    return nil
}

