// validateVolume performs strict validation on all GitRepo volume fields.
func validateVolume(src *v1.GitRepoVolumeSource) error {
    // Existing flag-style validation (unchanged)
    if err := validateNonFlagArgument(src.Repository, "repository"); err != nil {
        return err
    }
    if err := validateNonFlagArgument(src.Revision, "revision"); err != nil {
        return err
    }
    if err := validateNonFlagArgument(src.Directory, "directory"); err != nil {
        return err
    }

    // Additional hardening – reject unsafe characters or patterns that could be
    // interpreted by git as flags or escape the target path.
    if err := validateSafeGitValue(src.Repository, "repository"); err != nil {
        return err
    }
    if err := validateSafeGitValue(src.Revision, "revision"); err != nil {
        return err
    }
    if err := validateDirectoryName(src.Directory); err != nil {
        return err
    }

    return nil
}

// validateSafeGitValue ensures a repository or revision string contains only
// allowed characters and no whitespace / control characters.
func validateSafeGitValue(v, name string) error {
    if v == "" {
        return nil
    }

    // Disallow any whitespace or control characters.
    if strings.ContainsAny(v, " \t\r\n\v\f") {
        return fmt.Errorf("%s cannot contain whitespace or control characters", name)
    }

    // Allowlist of characters considered safe for git CLI arguments.
    var safe = regexp.MustCompile(`^[0-9A-Za-z._/@:+=-]+$`)
    if !safe.MatchString(v) {
        return fmt.Errorf("%s contains invalid characters", name)
    }
    return nil
}

