func isOriginAllowed(allows []string, origin string) bool {
    // Empty origin is never allowed
    if origin == "" {
        return false
    }

    // Extract host from the supplied origin (strip scheme & port)
    host := origin
    if u, err := url.Parse(origin); err == nil && u.Host != "" {
        host = u.Host
    }
    if h, _, err := net.SplitHostPort(host); err == nil {
        host = h
    }
    host = strings.ToLower(host)

    for _, o := range allows {
        if o == allOrigins {
            // Preserve existing wildcard behaviour ("*")
            return true
        }

        allowed := strings.ToLower(o)
        // Normalise the allowed entry in the same way (strip scheme & port)
        if u, err := url.Parse(allowed); err == nil && u.Host != "" {
            allowed = u.Host
        }
        if h, _, err := net.SplitHostPort(allowed); err == nil {
            allowed = h
        }

        // Exact match
        if host == allowed {
            return true
        }
        // Sub-domain match that respects dot boundary (e.g., x.example.com)
        if strings.HasSuffix(host, "."+allowed) {
            return true
        }
    }

    return false
}

