func isOriginAllowed(allows []string, origin string) bool {
    // Empty origin is never allowed
    if origin == "" {
        return false
    }

    // Helper to normalise a host (strip scheme, port, brackets, lower-case)
    sanitize := func(addr string) string {
        // remove scheme
        if idx := strings.Index(addr, "://"); idx != -1 {
            addr = addr[idx+3:]
        }

        // IPv6 literal with optional port: [::1]:8080
        if strings.HasPrefix(addr, "[") {
            if end := strings.Index(addr, "]"); end != -1 {
                addr = addr[1:end] // drop surrounding brackets
            }
        } else {
            // strip port for IPv4/hostname form
            if idx := strings.LastIndex(addr, ":"); idx != -1 {
                addr = addr[:idx]
            }
        }

        return strings.ToLower(addr)
    }

    host := sanitize(origin)
    if host == "" {
        return false
    }

    for _, o := range allows {
        if o == allOrigins { // preserve existing wildcard behaviour ("*")
            return true
        }

        allowed := sanitize(o)
        if allowed == "" {
            continue
        }

        // Exact match
        if host == allowed {
            return true
        }
        // Sub-domain match that respects dot boundary (e.g., x.example.com)
        if strings.HasSuffix(host, "."+allowed) {
            return true
        }
    }

    return false
}

