func isAllowedToRun(uid uint32, args []string) bool {
    // A command can run if any of the following are true:
    //     * It runs as root
    //     * It's contained in nonRootAllowed
    //     * It's a pure help request ("-h"/"--help" with no other option flags)
    // Note: commands still need valid context and snaps can only access own config.

    // Prevent panics on empty argument list and refuse execution when no command is supplied.
    if len(args) == 0 {
        return false
    }

    return uid == 0 ||
        strutil.ListContains(nonRootAllowed, args[0]) ||
        helpOnly(args)
}

// helpOnly returns true when the argument list represents an unprivileged
// help request, i.e. it contains at least one "-h" or "--help" flag and
// *no other* option flags (arguments that start with "-").
func helpOnly(args []string) bool {
    hasHelp := false
    for _, arg := range args {
        if strings.HasPrefix(arg, "-") {
            switch arg {
            case "-h", "--help":
                hasHelp = true
            default:
                // Another option flag is present -> not a pure help request.
                return false
            }
        }
    }
    return hasHelp
}

