var (
    // ErrNeedsLogin means the user should be redirected to the login page
    ErrNeedsLogin = errors.New("redirect to login page")

    // Used to check final redirects are not susceptible to open redirects.
    // The regex now blocks additional encoded variants that could be decoded by the
    // browser into an absolute URL, e.g. /%2F%2Fevil.com or /%5Cevil.com. It also
    // ignores any combination of whitespace, vertical-tab or CR/LF characters that
    // may be sneaked in between.
    //
    // Matches examples:
    //   //, /\, / /, / \ , /%2F, /%2f, /%5C, /%5c (and with spaces or CR/LF in-between)
    invalidRedirectRegex = regexp.MustCompile(`^/(?:\s|\v|%0[dD]|%0[aA])*(?:/|\\|%2[Ff]|%5[Cc])`)
)

