func (n *NodeInfo) FillAuthzContext(ctx *acl.AuthorizerContext) {
    // Ensure we have a valid receiver and context before attempting to
    // populate ACL information.  Skipping these checks would retain the
    // historical behaviour for nil values while preventing panics.
    if n == nil || ctx == nil {
        return
    }

    // Provide partition and namespace information for enterprise ACLs.
    ctx.SetPartition(n.EnterpriseMeta.PartitionOrEmpty())
    ctx.SetNamespace(n.EnterpriseMeta.NamespaceOrDefault())

    // Datacenter and peer name are also part of the ACL evaluation matrix.
    if n.Datacenter != "" {
        ctx.SetDatacenter(n.Datacenter)
    }
    if n.PeerName != "" {
        ctx.SetPeerName(n.PeerName)
    }
}

