patch:
func isRepositoryGitPath(path string) bool {
	// Reject suspicious control characters to mitigate argument/command injection.
	if strings.ContainsAny(path, "\x00\r\n") { // NUL, CR, LF
		return false
	}

	// Normalise directory separators to simplify the checks.
	normalized := strings.ReplaceAll(path, `\\`, `/`)
	normalized = strings.ToLower(normalized)

	// Quick exit if no ".git" at all.
	if !strings.Contains(normalized, ".git") {
		return false
	}

	// Split the path and evaluate each component.
	segments := strings.Split(normalized, "/")
	lastIdx := len(segments) - 1
	for idx, segment := range segments {
		// A dedicated ".git" or ".git." directory definitely represents a Git dir.
		if segment == ".git" || segment == ".git." {
			return true
		}

		// The final segment may legitimately end with ".git" (e.g. "repo.git").
		if idx == lastIdx && (strings.HasSuffix(segment, ".git") || strings.HasSuffix(segment, ".git.")) {
			return true
		}
	}

	return false
}

