func (p *OAuthProxy) IsValidRedirect(redirect string) bool {
	switch {
	case redirect == "":
		// The user didn't specify a redirect, should fallback to `/`
		return false
	case strings.HasPrefix(redirect, "/") && !strings.HasPrefix(redirect, "//") && !invalidRedirectRegex.MatchString(redirect):
		return true
	case strings.HasPrefix(redirect, "http://") || strings.HasPrefix(redirect, "https://"):
		redirectURL, err := url.Parse(redirect)
		if err != nil {
			logger.Printf("Rejecting invalid redirect %q: scheme unsupported or missing", redirect)
			return false
		}
		redirectHostname := redirectURL.Hostname()

		for _, allowedDomain := range p.whitelistDomains {
			allowedHost, allowedPort := splitHostPort(allowedDomain)
			if allowedHost == "" {
				continue
			}

			if redirectHostname == strings.TrimPrefix(allowedHost, ".") ||
				(strings.HasPrefix(allowedHost, ".") &&
					strings.HasSuffix(redirectHostname, allowedHost)) {
				// the domain names match, now validate the ports
				// if the whitelisted domain's port is '*', allow all ports
				// if the whitelisted domain contains a specific port, only allow that port
				// if the whitelisted domain doesn't contain a port at all, only allow empty redirect ports ie http and https
				redirectPort := redirectURL.Port()
				if allowedPort == "*" ||
					allowedPort == redirectPort ||
					(allowedPort == "" && redirectPort == "") {
					return true
				}
			}
		}

		logger.Printf("Rejecting invalid redirect %q: domain / port not in whitelist", redirect)
		return false
	default:
		logger.Printf("Rejecting invalid redirect %q: not an absolute or relative URL", redirect)
		return false
	}
}

patch:
/* hasDomainOrSubdomain returns true when candidateHost is either the exact
 * allowedDomain (if allowRoot is true) or a bonafide sub-domain of
 * allowedDomain (x.allowedDomain).  It guarantees that the match is separated
 * by a single dot so that strings such as "badexample.com" do not match
 * "example.com".
 */
func hasDomainOrSubdomain(candidateHost, allowedDomain string, allowRoot bool) bool {
    candidateHost = strings.ToLower(candidateHost)
    allowedDomain = strings.ToLower(allowedDomain)

    // Exact host match
    if candidateHost == allowedDomain {
        return allowRoot
    }

    // A sub-domain must be strictly longer than the parent domain
    if len(candidateHost) <= len(allowedDomain) {
        return false
    }

    if !strings.HasSuffix(candidateHost, allowedDomain) {
        return false
    }

    // Character immediately before the suffix must be '.'
    idx := len(candidateHost) - len(allowedDomain) - 1
    return idx >= 0 && candidateHost[idx] == '.'
}

func (p *OAuthProxy) IsValidRedirect(redirect string) bool {
    switch {
    case redirect == "":
        // The user didn't specify a redirect, should fallback to `/`
        return false
    case strings.HasPrefix(redirect, "/") && !strings.HasPrefix(redirect, "//") && !invalidRedirectRegex.MatchString(redirect):
        return true
    case strings.HasPrefix(redirect, "http://") || strings.HasPrefix(redirect, "https://"):
        redirectURL, err := url.Parse(redirect)
        if err != nil {
            logger.Printf("Rejecting invalid redirect %q: scheme unsupported or missing", redirect)
            return false
        }
        redirectHostname := strings.ToLower(redirectURL.Hostname())

        for _, domain := range p.whitelistDomains {
            if domain == "" {
                continue
            }

            // Keep a copy with the original leading dot (if present)
            originalDomain := domain
            domainHostname, domainPort := splitHostPort(strings.TrimLeft(domain, "."))
            if domainHostname == "" {
                continue
            }
            domainHostname = strings.ToLower(domainHostname)

            allowRoot := !strings.HasPrefix(originalDomain, ".")
            if hasDomainOrSubdomain(redirectHostname, domainHostname, allowRoot) {
                // Port validation (unchanged logic)
                redirectPort := redirectURL.Port()
                if domainPort == "*" || domainPort == redirectPort || (domainPort == "" && redirectPort == "") {
                    return true
                }
            }
        }

        logger.Printf("Rejecting invalid redirect %q: domain / port not in whitelist", redirect)
        return false
    default:
        logger.Printf("Rejecting invalid redirect %q: not an absolute or relative URL", redirect)
        return false
    }
}

