patch:
/* hasDomainOrSubdomain returns true when the candidateHost complies
 * with the following policy:
 *   - If allowRoot is true  (whitelist entry **without** leading dot)  ->
 *       ONLY the exact host is accepted – sub-domains are NOT allowed.
 *   - If allowRoot is false (whitelist entry **with**    leading dot)  ->
 *       ONLY real sub-domains are accepted – the root host is NOT allowed.
 *
 * A "real" sub-domain must be separated from the parent domain by a single
 * dot, so strings such as "badexample.com" do not match "example.com".
 */
func hasDomainOrSubdomain(candidateHost, allowedDomain string, allowRoot bool) bool {
    candidateHost = strings.ToLower(candidateHost)
    allowedDomain = strings.ToLower(allowedDomain)

    // Exact host match is allowed only when allowRoot == true
    if candidateHost == allowedDomain {
        return allowRoot
    }

    // If root host is allowed, sub-domains are explicitly forbidden
    if allowRoot {
        return false
    }

    // From this point we only reach the code path for sub-domain matches
    if len(candidateHost) <= len(allowedDomain) {
        return false
    }
    if !strings.HasSuffix(candidateHost, allowedDomain) {
        return false
    }

    // The character immediately before the suffix must be a dot (.)
    idx := len(candidateHost) - len(allowedDomain) - 1
    return idx >= 0 && candidateHost[idx] == '.'
}

