func Unpack(r io.Reader, dst string) error {
    // Determine an absolute destination path once.
    absDst, err := filepath.Abs(dst)
    if err != nil {
        return fmt.Errorf("failed to get absolute path for dst: %v", err)
    }

    // ---------------------------------------------------------------------
    // Helper that verifies a path (after filepath.Abs) is strictly under dst.
    // A trailing path separator is appended to avoid partial prefix matches.
    // ---------------------------------------------------------------------
    isWithinDst := func(p string) (bool, error) {
        abs, err := filepath.Abs(p)
        if err != nil {
            return false, err
        }
        abs = filepath.Clean(abs) + string(os.PathSeparator)
        base := absDst + string(os.PathSeparator)
        return strings.HasPrefix(abs, base), nil
    }

    // ---------------------------------------------------------------------
    // Helper that walks the path components (on disk) and detects if any
    // *existing* element in the hierarchy is a symlink.  We must *not*
    // follow symlinks, hence os.Lstat is used.
    // ---------------------------------------------------------------------
    hasSymlinkParent := func(fullPath string) (bool, error) {
        rel, err := filepath.Rel(absDst, fullPath)
        if err != nil {
            return false, err
        }
        parts := strings.Split(rel, string(os.PathSeparator))
        cur := absDst
        // Only check components that already exist on disk (parent dirs).
        for i := 0; i < len(parts)-1; i++ {
            cur = filepath.Join(cur, parts[i])
            fi, err := os.Lstat(cur)
            if err != nil {
                if os.IsNotExist(err) {
                    continue // nothing to check yet
                }
                return false, err
            }
            if fi.Mode()&os.ModeSymlink != 0 {
                return true, nil
            }
        }
        return false, nil
    }

    // Decompress as we read.
    uncompressed, err := gzip.NewReader(r)
    if err != nil {
        return fmt.Errorf("Failed to uncompress slug: %v", err)
    }

    // Untar as we read.
    untar := tar.NewReader(uncompressed)

    // Unpackage all the contents into the directory.
    for {
        header, err := untar.Next()
        if err == io.EOF {
            break
        }
        if err != nil {
            return fmt.Errorf("Failed to untar slug: %v", err)
        }

        // --- Secure name handling -----------------------------------------
        name := filepath.Clean(header.Name)
        if filepath.IsAbs(name) {
            name = name[1:] // strip leading '/'
        }
        if name == "" || name == "." || strings.HasPrefix(name, ".."+string(os.PathSeparator)) {
            return fmt.Errorf("invalid path %q in archive (possible traversal)", header.Name)
        }

        path := filepath.Join(absDst, name)

        // Ensure the final path (without following symlinks) stays inside dst.
        if ok, err := isWithinDst(path); err != nil || !ok {
            if err != nil {
                return fmt.Errorf("path validation error for %q: %v", path, err)
            }
            return fmt.Errorf("invalid path %q in archive (outside destination)", header.Name)
        }

        // For every non-symlink entry, ensure no component so far is a symlink.
        if header.Typeflag != tar.TypeSymlink {
            if symlinkFound, err := hasSymlinkParent(path); err != nil {
                return fmt.Errorf("symlink inspection error for %q: %v", path, err)
            } else if symlinkFound {
                return fmt.Errorf("Cannot extract %q through symlink", header.Name)
            }
        }

        // Make the directories to the path (parents).
        dir := filepath.Dir(path)
        if err := os.MkdirAll(dir, 0755); err != nil {
            return fmt.Errorf("Failed to create directory %q: %v", dir, err)
        }

        // ------------------ Symlink handling ------------------------------
        if header.Typeflag == tar.TypeSymlink {
            // Disallow absolute targets.
            if filepath.IsAbs(header.Linkname) {
                return fmt.Errorf("Invalid symlink (%q -> %q) has absolute target", header.Name, header.Linkname)
            }
            // Create the symlink as-is (target may point outside dst; this is
            // safe because we never write *through* it later).
            if err := os.Symlink(header.Linkname, path); err != nil {
                return fmt.Errorf("Failed creating symlink (%q -> %q): %v", header.Name, header.Linkname, err)
            }
            continue
        }

        // ------------------ Directory handling ---------------------------
        if header.Typeflag == tar.TypeDir {
            if err := os.MkdirAll(path, 0755); err != nil {
                return fmt.Errorf("Failed to create directory %q: %v", path, err)
            }
            continue
        }

        // Only unpack regular files from this point on.
        if header.Typeflag != tar.TypeReg && header.Typeflag != tar.TypeRegA {
            return fmt.Errorf("Failed creating %q: unsupported type %c", path, header.Typeflag)
        }

        // Open a handle to the destination.
        fh, err := os.Create(path)
        if err != nil {
            // Mimic tar's behavior w.r.t. duplicate files.
            if os.IsPermission(err) {
                os.Chmod(path, 0600)
                fh, err = os.Create(path)
            }
            if err != nil {
                return fmt.Errorf("Failed creating file %q: %v", path, err)
            }
        }

        // Copy the contents.
        _, err = io.Copy(fh, untar)
        fh.Close()
        if err != nil {
            return fmt.Errorf("Failed to copy slug file %q: %v", path, err)
        }

        // Restore the file mode (after writing in case it is read-only).
        mode := header.FileInfo().Mode()
        if err := os.Chmod(path, mode); err != nil {
            return fmt.Errorf("Failed setting permissions on %q: %v", path, err)
        }
    }
    return nil
}

