                    continue // nothing to check yet
                }
                return false, err
            }
            if fi.Mode()&os.ModeSymlink != 0 {
                return true, nil
            }
        }
        return false, nil
    }

    // Decompress as we read.
    uncompressed, err := gzip.NewReader(r)
    if err != nil {
        return fmt.Errorf("Failed to uncompress slug: %v", err)
    }

    // Untar as we read.
    untar := tar.NewReader(uncompressed)

