        if ok, err := isWithinDst(path); err != nil || !ok {
            if err != nil {
                return fmt.Errorf("path validation error for %q: %v", path, err)
            }
            return fmt.Errorf("invalid path %q in archive (outside destination)", header.Name)
        }

