func Unpack(r io.Reader, dst string) error {
    // ------------------------------------------------------------
    // Compute absolute destination path once for consistent checks.
    // ------------------------------------------------------------
    absDst, err := filepath.Abs(dst)
    if err != nil {
        return fmt.Errorf("failed to get absolute path for dst: %v", err)
    }

    // Helper that verifies a *resolved* path is strictly under dst.
    isWithin := func(p string) (bool, error) {
        resolved, err := filepath.EvalSymlinks(p)
        if err != nil {
            // If the exact path does not yet exist, walk upward until we find
            // something that does so we can still resolve intermediate symlinks.
            if os.IsNotExist(err) {
                cur := p
                for {
                    cur = filepath.Dir(cur)
                    if cur == "/" || cur == "." || cur == "" {
                        break
                    }
                    if rp, perr := filepath.EvalSymlinks(cur); perr == nil {
                        suffix := strings.TrimPrefix(p, cur)
                        resolved = filepath.Join(rp, suffix)
                        err = nil
                        break
                    } else if !os.IsNotExist(perr) {
                        return false, perr
                    }
                }
            } else {
                return false, err
            }
        }
        if resolved == "" {
            resolved = p
        }
        resolved, err = filepath.Abs(resolved)
        if err != nil {
            return false, err
        }
        base := absDst + string(os.PathSeparator)
        resolvedWithSep := resolved + string(os.PathSeparator)
        return strings.HasPrefix(resolvedWithSep, base), nil
    }

    // Decompress the incoming stream.
    uncompressed, err := gzip.NewReader(r)
    if err != nil {
        return fmt.Errorf("Failed to uncompress slug: %v", err)
    }

    // Untar as we read.
    untar := tar.NewReader(uncompressed)

    for {
        header, err := untar.Next()
        if err == io.EOF {
            break
        }
        if err != nil {
            return fmt.Errorf("Failed to untar slug: %v", err)
        }

        // Canonicalise the header name.
        name := filepath.Clean(header.Name)
        if filepath.IsAbs(name) {
            name = name[1:]
        }
        if name == "" || name == "." || strings.HasPrefix(name, ".."+string(os.PathSeparator)) {
            return fmt.Errorf("invalid path %q in archive (possible traversal)", header.Name)
        }

        destPath := filepath.Join(absDst, name)
        dir := filepath.Dir(destPath)

        switch header.Typeflag {
        case tar.TypeSymlink:
            // Validate the directory that will contain the link.
            if ok, err := isWithin(dir); err != nil {
                return fmt.Errorf("symlink inspection error for %q: %v", header.Name, err)
            } else if !ok {
                return fmt.Errorf("Cannot extract %q through symlink", header.Name)
            }

            // Disallow absolute link targets.
            if filepath.IsAbs(header.Linkname) {
                return fmt.Errorf("Invalid symlink (%q -> %q) has absolute target", header.Name, header.Linkname)
            }

            linkTarget := filepath.Join(dir, header.Linkname)
            if ok, err := isWithin(linkTarget); err != nil {
                return fmt.Errorf("symlink target validation error for (%q -> %q): %v", header.Name, header.Linkname, err)
            } else if !ok {
                return fmt.Errorf("Invalid symlink (%q -> %q) has external target", header.Name, header.Linkname)
            }

            if err := os.MkdirAll(dir, 0755); err != nil {
                return fmt.Errorf("Failed to create directory %q: %v", dir, err)
            }
            if err := os.Symlink(header.Linkname, destPath); err != nil {
                return fmt.Errorf("Failed creating symlink (%q -> %q): %v", header.Name, header.Linkname, err)
            }
            continue

        case tar.TypeDir:
            // Validate the directory itself.
            if ok, err := isWithin(destPath); err != nil {
                return fmt.Errorf("symlink inspection error for %q: %v", header.Name, err)
            } else if !ok {
                return fmt.Errorf("Cannot extract %q through symlink", header.Name)
            }

            if err := os.MkdirAll(destPath, 0755); err != nil {
                return fmt.Errorf("Failed to create directory %q: %v", destPath, err)
            }
            continue

        default:
            // Only regular files beyond this point.
            if header.Typeflag != tar.TypeReg && header.Typeflag != tar.TypeRegA {
                return fmt.Errorf("Failed creating %q: unsupported type %c", destPath, header.Typeflag)
            }

            // Ensure the final destination is safe (no traversal through symlinks).
            if ok, err := isWithin(destPath); err != nil {
                return fmt.Errorf("symlink inspection error for %q: %v", header.Name, err)
            } else if !ok {
                return fmt.Errorf("Cannot extract %q through symlink", header.Name)
            }

            // Do not clobber an existing symlink with a file.
            if fi, err := os.Lstat(destPath); err == nil && fi.Mode()&os.ModeSymlink != 0 {
                return fmt.Errorf("Cannot extract %q through symlink", header.Name)
            }

            if err := os.MkdirAll(dir, 0755); err != nil {
                return fmt.Errorf("Failed to create directory %q: %v", dir, err)
            }

            fh, err := os.Create(destPath)
            if err != nil {
                // Mimic tar's behaviour regarding duplicate files & perms.
                if os.IsPermission(err) {
                    os.Chmod(destPath, 0600)
                    fh, err = os.Create(destPath)
                }
                if err != nil {
                    return fmt.Errorf("Failed creating file %q: %v", destPath, err)
                }
            }

            if _, err = io.Copy(fh, untar); err != nil {
                fh.Close()
                return fmt.Errorf("Failed to copy slug file %q: %v", destPath, err)
            }
            fh.Close()

            if err := os.Chmod(destPath, header.FileInfo().Mode()); err != nil {
                return fmt.Errorf("Failed setting permissions on %q: %v", destPath, err)
            }
        }
    }
    return nil
}

