func isLoopbackURI(requested *url.URL, registeredURI string) bool {
    registered, err := url.Parse(registeredURI)
    if err != nil {
        return false
    }

    // Both URIs must use HTTP scheme and resolve to loopback addresses.
    if registered.Scheme != "http" || requested.Scheme != "http" {
        return false
    }
    if !isLoopbackAddress(registered.Hostname()) || !isLoopbackAddress(requested.Hostname()) {
        return false
    }

    // The hostname (without port) must be identical (port may differ).
    if !strings.EqualFold(registered.Hostname(), requested.Hostname()) {
        return false
    }

    // Paths must match exactly.
    if registered.Path != requested.Path {
        return false
    }

    // All query parameters present in the registered URI must also be present in the requested one.
    regQuery := registered.Query()
    reqQuery := requested.Query()
    for key, regVals := range regQuery {
        reqVals, ok := reqQuery[key]
        if !ok || len(reqVals) != len(regVals) {
            return false
        }
        // Ensure each value is present (order-independent).
        for _, rv := range regVals {
            found := false
            for _, qv := range reqVals {
                if rv == qv {
                    found = true
                    break
                }
            }
            if !found {
                return false
            }
        }
    }

    return true
}

