func isMatchingRedirectURI(uri string, haystack []string) bool {
    requested, err := url.Parse(uri)
    if err != nil {
        return false
    }

    for _, candidate := range haystack {
        // Fast path: identical literal strings (case-sensitive)
        if candidate == uri {
            return true
        }

        // Component-wise comparison (safer than EqualFold on the whole URI)
        reg, err := url.Parse(candidate)
        if err != nil {
            continue
        }

        if urlsComponentWiseEqual(requested, reg) {
            return true
        }

        // Finally, apply the stricter loop-back validation.
        if isLoopbackURI(requested, candidate) {
            return true
        }
    }
    return false
}

// urlsComponentWiseEqual performs a safe component-wise comparison of two
// URIs.  Scheme and host are compared case-insensitively, path is compared
// case-sensitively, and queries are treated order-independently.
func urlsComponentWiseEqual(a, b *url.URL) bool {
    if !strings.EqualFold(a.Scheme, b.Scheme) {
        return false
    }
    if !strings.EqualFold(a.Host, b.Host) {
        return false
    }
    if a.Path != b.Path {
        return false
    }
    return queryEquals(a.Query(), b.Query())
}

// queryEquals returns true if the two query value sets are identical
// (order-independent).
func queryEquals(q1, q2 url.Values) bool {
    if len(q1) != len(q2) {
        return false
    }
    for k, v1 := range q1 {
        v2, ok := q2[k]
        if !ok || len(v1) != len(v2) {
            return false
        }
        for i := range v1 {
            if v1[i] != v2[i] {
                return false
            }
        }
    }
    return true
}

