        return false
    }

    // 4. Path handling – it MUST exist on the registered URI and match exactly.
    if registered.Path == "" || registered.Path != requested.Path {
        return false
    }

    // 5. Port handling – if the registered URI specifies a port, the same port is required.
    if regPort := registered.Port(); regPort != "" {
        if regPort != requested.Port() {
            return false
        }
    }
    // If the registered URI has no port we intentionally allow any port on the requested URI
    // (RFC8252 §7.3 – native apps may vary the ephemeral port).

    // 6. Queries must match exactly (order-independent, value-set identical).
    if !queryEquals(registered.Query(), requested.Query()) {
        return false
    }

