def get_doc_md(self, doc_md: str | None) -> str | None:
    """Safely render the ``doc_md`` content.

    This implementation ensures that every template—whether provided as an
    inline string or a file name—is rendered using the sandboxed Jinja
    environment obtained via ``get_template_env(force_sandboxed=True)``.
    This prevents DAG authors from executing arbitrary code by bypassing the
    sandbox with inline template strings.
    """
    if doc_md is None:
        return doc_md

    # Always use a sandboxed Jinja environment.
    env = self.get_template_env(force_sandboxed=True)

    try:
        if doc_md.endswith('.md'):
            # Load a template file through the sandboxed environment
            template = env.get_template(doc_md)
        else:
            # Build a template from the raw string inside the same sandboxed env
            template = env.from_string(doc_md)
    except jinja2.exceptions.TemplateNotFound:
        return (
            f"""
            # Templating Error!
            Not able to find the template file: `{doc_md}`.
            """
        )
    except jinja2.exceptions.TemplateError as exc:
        # Gracefully handle template-related errors and avoid exposing internals.
        return f"""
        # Templating Error!
        {exc}
        """

    # Render with no additional context (original behaviour) inside sandbox.
    return template.render()

