const { execFileSync } = require('child_process');

exports.killByPort = function (port) {
  // Ensure the provided port is valid and numeric
  if (!/^\d+$/.test(String(port))) {
    throw new Error('Invalid port: must be a numeric value');
  }

  var portNumber = parseInt(port, 10);
  if (portNumber < 1 || portNumber > 65535) {
    throw new Error('Invalid port: out of range 1-65535');
  }

  var stdout;
  try {
    // Use execFileSync to avoid shell interpretation and pass arguments safely
    stdout = execFileSync('lsof', ['-t', '-i', ':' + portNumber], { encoding: 'utf8' });
  } catch (e) {
    // Either lsof failed or no process is listening on the port; nothing to kill
    return;
  }

  var pids = stdout.split('\n').filter(Boolean);

  pids.forEach(function (pid) {
    try {
      // Use Node's built-in process.kill for safe termination
      process.kill(parseInt(pid, 10));
    } catch (e) {
      // Ignore errors for processes that may have already exited or insufficient privileges
    }
  });
};

