const { execFileSync } = require('child_process');

/**
 * Kill any processes currently listening on the given port.
 *
 * @param {number|string} port - TCP/UDP port to free.
 * @throws {TypeError|Error} If the argument type or value is invalid.
 */
exports.killByPort = function (port) {
  // Accept string or number only
  if (typeof port !== 'string' && typeof port !== 'number') {
    throw new TypeError('Port must be a string or number');
  }

  // Canonicalise and validate numeric form
  const portStr = String(port).trim();
  if (!/^[0-9]+$/.test(portStr)) {
    throw new Error('Invalid port: must contain only digits');
  }

  const portNum = Number(portStr);
  if (portNum < 1 || portNum > 65535) {
    throw new Error('Invalid port: out of range 1-65535');
  }

  let stdout;
  try {
    // Exec without a shell; lsof prints PIDs listening on the port
    stdout = execFileSync('lsof', ['-t', '-i', `:${portNum}`], { encoding: 'utf8' });
  } catch (_) {
    // Either lsof failed or nothing is listening. Nothing to kill.
    return;
  }

  // Split output into individual PIDs and terminate them
  const pids = stdout.split('\n').filter(Boolean);
  pids.forEach(function (pidStr) {
    const pid = Number(pidStr);
    if (!Number.isNaN(pid)) {
      try {
        process.kill(pid);
      } catch (_) {
        // Ignore errors such as insufficient privileges or already-exited process
      }
    }
  });
};

