const { spawnSync } = require('child_process');

// Simple allow-list validation for npm package names (scoped and unscoped)
function isValidPackageName(name) {
    /*
     * Matches examples:
     *   unscoped: my-package
     *   scoped  : @scope/my-package
     */
    return /^(@[a-z0-9._-]+\/)?[a-z0-9._-]+$/i.test(name);
}

module.exports = function (packageName, { registry = '', timeout = null } = {}) {
    try {
        // 1. Strict input validation to mitigate command injection
        if (typeof packageName !== 'string' || !isValidPackageName(packageName)) {
            throw new Error('Invalid package name provided');
        }
        if (registry && typeof registry !== 'string') {
            throw new Error('Invalid registry provided');
        }

        // 2. Build argument list safely (no shell interpretation)
        const args = ['view', packageName, 'version'];
        if (registry) {
            args.push('--registry', registry);
        }

        const config = {
            stdio: ['pipe', 'pipe', 'ignore'],
            encoding: 'utf8'
        };
        if (timeout) {
            config.timeout = timeout;
        }

        // 3. Execute command in a shell-free context
        const result = spawnSync('npm', args, config);

        // 4. Return behaviour consistent with the original implementation
        if (result.error || result.status !== 0) {
            return null;
        }

        const version = result.stdout;
        if (version) {
            return version.toString().trim().replace(/^\n*/, '').replace(/\n*$/, '');
        }
        return null;

    } catch (err) {
        return null;
    }
};

