module.exports = function(path, opts, cb) {
  if (!cb) {
    cb = opts;
    opts = {};
  }

  // Ensure opts is always an object
  opts = opts || {};

  /* -----------------------------
   * Security Fix START
   * ----------------------------- */
  // 1. Validate the optional "exec" parameter to prevent command-injection
  if (typeof opts.exec === 'string') {
    // Allow only alphanumerics, underscore, dash, slash and dot
    const SAFE_EXEC_PATTERN = /^[\w\-\/\.]+$/;
    if (!SAFE_EXEC_PATTERN.test(opts.exec)) {
      return cb(new Error('Invalid characters detected in "exec" option'));
    }
  }

  // 2. Whitelist recognised options for child_process.exec
  const execOptions = {
    cwd: opts.cwd,
    env: opts.env,
    encoding: opts.encoding,
    shell: opts.shell,
    timeout: opts.timeout || 5000,
    maxBuffer: opts.maxBuffer,
    killSignal: opts.killSignal,
    uid: opts.uid,
    gid: opts.gid,
    windowsHide: opts.windowsHide
  };
  /* -----------------------------
   * Security Fix END
   * ----------------------------- */

  var cmd = module.exports.cmd(path, opts);

  exec(cmd, execOptions, function(e, stdout, stderr) {
    if (e) { return cb(e); }
    if (stderr) { return cb(new Error(stderr)); }

    return cb(null, module.exports.parse(path, stdout, opts));
  });
};

