import os
from mlflow.exceptions import MlflowException
from mlflow.protos.databricks_pb2 import INVALID_PARAMETER_VALUE


def _sanitize_relative_path(path):
    """Validate and normalise an artifact path to block directory-traversal attacks."""
    if path is None:
        return None
    path = str(path)
    normalised = os.path.normpath(path)
    drive, _ = os.path.splitdrive(normalised)
    if os.path.isabs(normalised) or drive:
        raise MlflowException(
            message="Invalid artifact path: absolute paths are not allowed.",
            error_code=INVALID_PARAMETER_VALUE,
        )
    if normalised.startswith(os.pardir) or f"{os.sep}{os.pardir}{os.sep}" in normalised:
        raise MlflowException(
            message="Invalid artifact path: directory traversal is not allowed.",
            error_code=INVALID_PARAMETER_VALUE,
        )
    return "" if normalised in (".", "") else normalised


def _list_artifacts():
    request_message = _get_request_message(
        ListArtifacts(),
        schema={
            "run_id": [_assert_string, _assert_required],
            "path": [_assert_string],
            "page_token": [_assert_string],
        },
    )
    response_message = ListArtifacts.Response()

    if request_message.HasField("path"):
        raw_path = request_message.path
        path = _sanitize_relative_path(raw_path)  # ---- NEW validation ----
    else:
        path = None

    run_id = request_message.run_id or request_message.run_uuid
    run = _get_tracking_store().get_run(run_id)

    if _is_servable_proxied_run_artifact_root(run.info.artifact_uri):
        artifact_entities = _list_artifacts_for_proxied_run_artifact_root(
            proxied_artifact_root=run.info.artifact_uri,
            relative_path=path,
        )
    else:
        artifact_entities = _get_artifact_repo(run).list_artifacts(path)

    response_message.files.extend([a.to_proto() for a in artifact_entities])
    response_message.root_uri = run.info.artifact_uri
    response = Response(mimetype="application/json")
    response.set_data(message_to_json(response_message))
    return response

