from mlflow.exceptions import MlflowException
from mlflow.protos.databricks_pb2 import INVALID_PARAMETER_VALUE


def _sanitize_relative_path(path):
    """Validate and normalise an artifact path to block directory-traversal attacks."""
    if path is None:
        return None
    path = str(path)
    normalised = os.path.normpath(path)
    drive, _ = os.path.splitdrive(normalised)
    if os.path.isabs(normalised) or drive:
        raise MlflowException(
            message="Invalid artifact path: absolute paths are not allowed.",
            error_code=INVALID_PARAMETER_VALUE,
        )
    if normalised.startswith(os.pardir) or f"{os.sep}{os.pardir}{os.sep}" in normalised:
        raise MlflowException(
            message="Invalid artifact path: directory traversal is not allowed.",
            error_code=INVALID_PARAMETER_VALUE,
        )
    return "" if normalised in (".", "") else normalised


