test: function ConnectionTester(host, port, callbackOrConnectTimeout, callback) {

    // ---------------------------------------------------------------------
    // Security hardening: validate **all** externally-controlled inputs to
    // prevent command-injection when they are later interpolated into
    // shell commands (see CVE-2023-XXXX / CWE-77).
    // ---------------------------------------------------------------------
    if (typeof host !== 'string' || host.length === 0) {
        throw new Error('Invalid host: expected non-empty string');
    }
    /*
     * Acceptable characters for host:
     *   - A–Z / a–z / 0–9
     *   - dot           (.)   – sub-domains / IPv4
     *   - dash          (-)   – hostnames like my-host
     *   - colon         (:)   – IPv6 literal
     * Anything else (spaces, semicolons, backticks, etc.) is rejected to
     * stop command injection vectors.
     */
    var HOST_RE = /^[A-Za-z0-9.:-]+$/;
    if (!HOST_RE.test(host)) {
        throw new Error('Invalid host: illegal characters detected');
    }

    // Port must be a number within the valid TCP range.
    var portNum = Number(port);
    if (!Number.isInteger(portNum) || portNum < 1 || portNum > 65535) {
        throw new Error('Invalid port: must be an integer between 1 and 65535');
    }

