ImageProto.stream = function(type, writer) {

    var self = this;

    // ensure minification is performed once (original behaviour)
    !self.builder.length && self.minify();

    /*
        -----------------------------------------------------------------
        SECURITY PATCH
        -----------------------------------------------------------------
        1.  Sanitise the `type` parameter (keep only the first alphanumeric
            segment, max 20 chars).
        2.  Make sure we NEVER spawn the process inside a shell by forcing
            `shell:false`.
        3.  Gracefully fall back to ImageMagick's `convert` when `gm`
            (GraphicsMagick) is not installed, preventing ENOENT crashes
            without changing the public API.
    */

    if (typeof type !== 'string' || !type.length)
        type = self.outputType;

    if (typeof type === 'string') {
        var match = type.match(/^[a-zA-Z0-9]{1,20}/);
        type = (match ? match[0] : (self.outputType || '')).toLowerCase();
    }
    /* --------------------------------------------------------------- */

    F.stats.performance.open++;

    // Arguments fed to gm/convert
    var args = self.arg(
        self.filename ? wrap(self.filename) : '-',
        (type ? type + ':' : '') + '-'
    );

    // Ensure we never spawn inside a shell
    var safeSpawnOpt = Object.assign({}, SPAWN_OPT, { shell: false });

    // -----------------------------------------------------------------
    // Pick the actual binary to execute (gm preferred, fallback convert)
    // -----------------------------------------------------------------
    var convertCmd = CMD_CONVERT[self.cmdarg] || 'gm';
    try {
        // Will throw ENOENT if the binary is missing
