        convertCmd = 'convert';
    }
    // -----------------------------------------------------------------

    var cmd = spawn(convertCmd, args, safeSpawnOpt);

    if (self.currentStream) {
        if (self.currentStream instanceof Buffer)
            cmd.stdin.end(self.currentStream);
        else
            self.currentStream.pipe(cmd.stdin);
