func newMysqlQueryEndpoint(datasource *models.DataSource) (tsdb.TsdbQueryEndpoint, error) {
    logger := log.New("tsdb.mysql")

    //---------------------------------------------------------------------
    // Helper functions for minimal, targeted percent-encoding. We avoid
    // introducing new imports by using strings.Replacer.
    //---------------------------------------------------------------------
    escapeUserOrPass := func(s string) string {
        return strings.NewReplacer(
            "@", "%40",
            ":", "%3A",
        ).Replace(s)
    }

    escapeAddr := func(s string) string {
        // Only encode the closing parenthesis that would otherwise break
        // the surrounding  tcp(<addr>)  wrapper.
        return strings.NewReplacer(
            ")", "%29",
        ).Replace(s)
    }

    escapeDB := func(s string) string {
        return strings.NewReplacer(
            "?", "%3F",
        ).Replace(s)
    }

    //---------------------------------------------------------------------
    // Decide protocol and apply escaping per DSN component.
    //---------------------------------------------------------------------
    protocol := "tcp"
    addr := datasource.Url
    if strings.HasPrefix(addr, "/") {
        protocol = "unix"
        // For unix sockets we keep the raw path so that the driver can
        // find the file. (No escaping here.)
    } else {
        addr = escapeAddr(addr)
    }

    user := escapeUserOrPass(datasource.User)
    passwd := escapeUserOrPass(datasource.DecryptedPassword())
    dbName := escapeDB(datasource.Database)

    //---------------------------------------------------------------------
    // Build DSN safely.
    //---------------------------------------------------------------------
    cnnstr := fmt.Sprintf("%s:%s@%s(%s)/%s?collation=utf8mb4_unicode_ci&parseTime=true&loc=UTC&allowNativePasswords=true",
        user,
        passwd,
        protocol,
        addr,
        dbName,
    )

