func (fem *FailedEventsManagerT) DropFailedRecordIDs(taskRunID string) {
    if !failedKeysEnabled {
        return
    }

    // Validate taskRunID to prevent SQL-injection via crafted table names.
    // Only allow letters, digits and underscore.
    if !isValidIdentifier(taskRunID) {
        pkgLogger.Errorf("Invalid taskRunID supplied: %s", taskRunID)
        return
    }

    // Compose and safely quote the table name.
    table := fmt.Sprintf("%s_%s", failedKeysTablePrefix, taskRunID)
    quotedTable := pq.QuoteIdentifier(table) // "table_name" with embedded quotes doubled

    sqlStatement := fmt.Sprintf("DROP TABLE IF EXISTS %s", quotedTable)
    if _, err := fem.dbHandle.Exec(sqlStatement); err != nil {
        pkgLogger.Errorf("Failed to drop table %s with error: %v", taskRunID, err)
    }
}

// isValidIdentifier returns true if id consists solely of A-Z, a-z, 0-9 or _.
// It prevents attackers from injecting SQL meta-characters.
var identifierRegexp = regexp.MustCompile(`^[A-Za-z0-9_]+$`)

func isValidIdentifier(id string) bool {
    return identifierRegexp.MatchString(id)
}

