// identifierRegexp ensures only [A-Za-z0-9_] are accepted in identifiers.
var identifierRegexp = regexp.MustCompile(`^[A-Za-z0-9_]+$`)

// isValidIdentifier returns true if id consists solely of A-Z, a-z, 0-9 or _.
func isValidIdentifier(id string) bool {
    return identifierRegexp.MatchString(id)
}

// quoteIdentifier safely quotes a PostgreSQL identifier.
// It wraps the identifier in double quotes and doubles any embedded quotes.
func quoteIdentifier(id string) string {
    return "\"" + strings.ReplaceAll(id, "\"", "\"\"") + "\""
