// isValidIdentifier ensures the supplied identifier contains only alphanumeric
// characters or underscores. Rejecting anything else prevents SQL-injection when
// the identifier is later interpolated into a query.
func isValidIdentifier(id string) bool {
    if id == "" {
        return false
    }
    for _, r := range id {
        if !(r == '_' || (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')) {
            return false
        }
    }
    return true
}

