func (r *MySQL) getSQL(str string) (string, error) {
    // 1. Basic input validation
    str = strings.TrimSpace(str)
    if str == "" {
        return "", fmt.Errorf("Empty SQL data")
    }

    // 2. Expect exactly five parts: db:table:field:key:value
    parts := strings.Split(str, ":")
    if len(parts) != 5 {
        return "", fmt.Errorf("Invalid SQL data - [%s]. (syntax: database:table:field:key:value)", str)
    }

    dbName, tableName := parts[0], parts[1]
    fieldName, keyName := parts[2], parts[3]
    valueStr := parts[4]

    // 3. Ensure the value portion is an integer (query demands it)
    valueInt, err := strconv.Atoi(valueStr)
    if err != nil {
        return "", fmt.Errorf("Invalid SQL data - [%s], the value must be int", str)
    }

    // 4. Escape identifiers properly and wrap them with back-ticks
    escapeIdent := func(s string) string {
        // Order matters: backslash first
        s = strings.ReplaceAll(s, "\\", "\\\\") // \\ ➜ \\\\
