func (i *Instance) CreateNewConnection(listenPort int, username string, remoteIpAddr string, remotePort int) error {
    // 1. Validate the username – only allow A–Z, a–z, 0–9, '.', '_', '-'.
    if username != "" {
        for _, ch := range username {
            if !(ch >= 'A' && ch <= 'Z' ||
                ch >= 'a' && ch <= 'z' ||
                ch >= '0' && ch <= '9' ||
                ch == '.' || ch == '_' || ch == '-') {
                return fmt.Errorf("invalid username: %s", username)
            }
        }
    }

    // 2. Build the user@host form (username may be empty).
    connAddr := remoteIpAddr
    if username != "" {
        connAddr = username + "@" + remoteIpAddr
    }

    configPath := filepath.Join(filepath.Dir(i.ExecPath), ".gotty")

    // Title shown in gotty tab.
    title := connAddr
    if remotePort != 22 {
        title += ":" + strconv.Itoa(remotePort)
    }

    // 3. Compose gotty arguments WITHOUT involving an extra shell.
    cmdArgs := []string{
        "-w",
        "-p", strconv.Itoa(listenPort),
        "--once",
        "--config", configPath,
        "--title-format", title,
        // Command that gotty should run (ssh in interactive mode).
        "ssh", "-tt", "-p", strconv.Itoa(remotePort), "--", connAddr,
    }

    cmd := exec.Command(i.ExecPath, cmdArgs...)
    cmd.Dir = filepath.Dir(i.ExecPath)
    cmd.Env = append(os.Environ(), "TERM=xterm")
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr

    // Launch asynchronously so CreateNewConnection returns immediately.
    go func() {
        _ = cmd.Run()
        i.Destroy()
    }()

    // Record instance metadata.
    i.tty = cmd
    i.AssignedPort = listenPort
    i.RemoteAddr = remoteIpAddr
    i.RemotePort = remotePort

    // 4. Create reverse-proxy to the gotty instance.
    path, err := url.Parse("http://127.0.0.1:" + strconv.Itoa(listenPort))
    if err != nil {
        return err
    }

    proxy := reverseproxy.NewReverseProxy(path)
    i.conn = proxy
    return nil
}

