    return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

// isDigit reports whether the rune is a digit (0-9).
func isDigit(r rune) bool {
    return r >= '0' && r <= '9'
}

// NewSortParameter constructs a SortParameter from the provided admin.Sort
// and an optional allow-list of sortable column names. The function now
// validates the sort key rigorously to prevent SQL-injection while
// retaining the original behaviour for valid inputs.
func NewSortParameter(sort *admin.Sort, allowedFields sets.String) (SortParameter, error) {
    //-------------------------------------------------------------------
    // 0. Sanity checks
    //-------------------------------------------------------------------
    if sort == nil {
        return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "sort parameter cannot be nil")
    }
    if sort.Key == "" {
        return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "invalid sort key specified: %v", sort.Key)
    }

    //-------------------------------------------------------------------
    // 1. Allow-list check (if caller supplied one)
    //-------------------------------------------------------------------
    if len(allowedFields) > 0 && !allowedFields.Has(sort.Key) {
        return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "unsupported sort key specified: %v", sort.Key)
    }

    //-------------------------------------------------------------------
    // 2. Character-level validation (defence-in-depth)
    //-------------------------------------------------------------------
    for i, ch := range sort.Key {
        if i == 0 {
            if !(isLetter(ch) || ch == '_') {
                return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "sort key must start with a letter or underscore: %v", sort.Key)
            }
        } else {
            if !(isLetter(ch) || isDigit(ch) || ch == '_') {
                return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "invalid characters in sort key: %v", sort.Key)
            }
        }
    }

    //-------------------------------------------------------------------
    // 3. Build the GORM order expression (original logic preserved)
    //-------------------------------------------------------------------
    var gormOrderExpression string
    switch sort.Direction {
    case admin.Sort_DESCENDING:
        gormOrderExpression = fmt.Sprintf(gormDescending, sort.Key)
    case admin.Sort_ASCENDING:
        gormOrderExpression = fmt.Sprintf(gormAscending, sort.Key)
    default:
        return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "invalid sort order specified: %v", sort)
    }

    return &sortParamImpl{
        gormOrderExpression: gormOrderExpression,
    }, nil
}

