import (
    "archive/tar"
    "errors"
    "fmt"
    "io"
    "os"
    "path/filepath"
    "strings"
)

// tarVisitor is exposed for test purposes and will be (re)assigned
// each time UntarToDirectory is invoked.
var tarVisitor func(entry TarFileEntry) error

func UntarToDirectory(reader io.Reader, dst string) error {
    // ensure we work with a clean, absolute destination path
    dstClean := filepath.Clean(dst)

    // define (and expose) the visitor used while iterating the TAR entries
    tarVisitor = func(entry TarFileEntry) error {
        // 1) normalise the entry name coming from the TAR header
        cleanedName := filepath.Clean(entry.Header.Name)
        // remove any leading path separator so that Join does not ignore dstClean
        cleanedName = strings.TrimPrefix(cleanedName, string(os.PathSeparator))

        // 2) reject attempts to traverse outside the destination directory
        if cleanedName == ".." || strings.HasPrefix(cleanedName, ".."+string(os.PathSeparator)) {
            return fmt.Errorf("illegal file path in tar: %q", entry.Header.Name)
        }

        // 3) build the absolute target path *after* validation
        target := filepath.Join(dstClean, cleanedName)

        // ensure the final target is still inside dstClean
        if target != dstClean && !strings.HasPrefix(target, dstClean+string(os.PathSeparator)) {
            return fmt.Errorf("illegal file path in tar: %q", entry.Header.Name)
        }

        switch entry.Header.Typeflag {
        case tar.TypeDir:
            // ensure directory exists (idempotent)
            return os.MkdirAll(target, 0o755)

        case tar.TypeReg:
            // make sure the parent directory exists first
            if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
                return err
            }

            f, err := os.OpenFile(target, os.O_CREATE|os.O_RDWR|os.O_TRUNC, os.FileMode(entry.Header.Mode))
            if err != nil {
                return err
            }
            defer func() {
                if cerr := f.Close(); cerr != nil {
                    log.Errorf("failed to close file during untar of path=%q: %v", f.Name(), cerr)
                }
            }()

            // limit the reader on each file read to prevent decompression bomb attacks
            numBytes, err := io.Copy(f, io.LimitReader(entry.Reader, perFileReadLimit))
            if numBytes >= perFileReadLimit || errors.Is(err, io.EOF) {
                return fmt.Errorf("zip read limit hit (potential decompression bomb attack)")
            }
            if err != nil {
                return fmt.Errorf("unable to copy file: %w", err)
            }
        }
        return nil
    }

    return IterateTar(reader, tarVisitor)
}

