func UntarToDirectory(reader io.Reader, dst string) error {
    // Resolve a canonical destination path once (prevents traversal via symlinks in dst)
    dstClean, err := filepath.Abs(dst)
    if err != nil {
        return fmt.Errorf("unable to resolve destination path: %w", err)
    }

    visitor := func(entry TarFileEntry) error {
        // 1) sanitise header name coming from the TAR
        name := filepath.Clean(entry.Header.Name)

        // 2) ensure the name is treated as *relative* (strip absolute prefixes)
        for len(name) > 0 && (name[0] == '/' || name[0] == '\\') {
            name = name[1:]
        }
        if name == "" || name == "." {
            return fmt.Errorf("illegal file path in tar: %q", entry.Header.Name)
        }

        // 3) create the absolute target path
        target := filepath.Join(dstClean, name)

        // 4) verify the target is still within dstClean (prevents path traversal)
        rel, err := filepath.Rel(dstClean, target)
        if err != nil {
            return fmt.Errorf("unable to compute relative path: %w", err)
        }
        // the following avoids importing the strings package
        prefix := ".." + string(os.PathSeparator)
        if rel == ".." || (len(rel) >= len(prefix) && rel[:len(prefix)] == prefix) {
            return fmt.Errorf("illegal file path in tar: %q", entry.Header.Name)
        }

        switch entry.Header.Typeflag {
        case tar.TypeDir:
            // ensure directory exists (idempotent)
            return os.MkdirAll(target, 0o755)

        case tar.TypeReg:
            // create parent directory first
            if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
                return err
            }

            f, err := os.OpenFile(target, os.O_CREATE|os.O_RDWR|os.O_TRUNC, os.FileMode(entry.Header.Mode))
            if err != nil {
                return err
            }
            defer func() {
                if cerr := f.Close(); cerr != nil {
                    log.Errorf("failed to close file during untar of path=%q: %v", f.Name(), cerr)
                }
            }()

            // limit the reader on each file read to prevent decompression bombs
            numBytes, err := io.Copy(f, io.LimitReader(entry.Reader, perFileReadLimit))
