/* sanitizeRsyncArgs validates the provided rsync arguments and makes sure that
   no dangerous options are passed to the underlying rsync binary. If an
   unsafe option is found an error is returned. */
func sanitizeRsyncArgs(args []string) error {
    // List of options that must never be accepted from the client because they
    // can be abused to access files outside the user scope or to execute
    // arbitrary commands.
    disallowed := []string{
        "--rsync-path", "--rsh", "-e", "--remote-shell", "--daemon", "--config",
        "--password-file", "--temp-dir", "--partial-dir", "--link-dest",
        "--compare-dest", "--copy-dest", "--backup-dir", "--sockopts",
    }
    for _, a := range args {
        for _, d := range disallowed {
            if a == d || strings.HasPrefix(a, d+"=") {
                return errors.New("disallowed rsync option: " + a)
            }
        }
    }
    return nil
}

