        if err := sanitizeRsyncArgs(args); err != nil {
            c.connection.Log(logger.LevelError, "rejected rsync command: %v", err)
            return command, err
        }

        // 2. Enforce safe/munge links while preserving the expected order
        if c.connection.User.HasPerm(dataprovider.PermCreateSymlinks, c.getDestPath()) {
            args = insertOptionBeforeFirstPath(args, "--safe-links")
        } else {
            args = insertOptionBeforeFirstPath(args, "--munge-links")
        }
    }

    c.connection.Log(logger.LevelDebug, "new system command %q, with args: %+v fs path %q quota check path %q", c.command, args, fsPath, quotaPath)
    cmd := exec.Command(c.command, args...)
    uid := c.connection.User.GetUID()
    gid := c.connection.User.GetGID()
    cmd = wrapCmd(cmd, uid, gid)
    command.cmd = cmd
    command.fsPath = fsPath
    command.quotaCheckPath = quotaPath
    command.fs = fs
    return command, nil
}

// insertOptionBeforeFirstPath adds the given option before the first argument
// that does not start with '-' (usually the source path). This keeps the order
// expected by rsync and the unit-tests.
func insertOptionBeforeFirstPath(args []string, opt string) []string {
    if util.Contains(args, opt) {
        return args
    }
    for idx, a := range args {
        if !strings.HasPrefix(a, "-") {
            newArgs := append([]string{}, args[:idx]...)
            newArgs = append(newArgs, opt)
            newArgs = append(newArgs, args[idx:]...)
            return newArgs
        }
    }
    // fallback: all args are options
    return append(args, opt)
}

// sanitizeRsyncArgs makes sure that no dangerous options are passed to rsync.
// It is intentionally strict: anything not explicitly allowed is rejected.
func sanitizeRsyncArgs(args []string) error {
    // Unit-tests sometimes prepend the binary name itself, skip it.
    if len(args) > 0 && args[0] == "rsync" {
        args = args[1:]
    }

    disallowed := map[string]struct{}{
        "--rsync-path":    {}, "--rsh":          {}, "-e":              {}, "--remote-shell":  {},
        "--daemon":        {}, "--config":       {}, "--password-file": {}, "--temp-dir":      {},
        "--partial-dir":   {}, "--partial":      {}, "--delay-updates": {}, "--link-dest":     {},
        "--compare-dest":  {}, "--copy-dest":    {}, "--backup-dir":    {}, "--backup":        {},
        "-b":              {}, "--sockopts":     {}, "--compress":      {}, "--compress-level":{}, "-z":{},
        "--owner":         {}, "-o":             {}, "--group":         {}, "-g":             {},
        "--times":         {}, "-t":             {}, "--perms":         {}, "-p":             {},
        "--chmod":         {}, "--chown":        {}, "--devices":       {}, "-D":             {},
        "--specials":      {}, "--xattrs":       {}, "-X":             {}, "--sparse":       {}, "-S":{},
        "--acls":          {}, "-A":             {}, "--hard-links":    {}, "-H":             {},
        "--copy-links":    {}, "-L":             {}, "--keep-dirlinks": {}, "-K":             {},
        "--delete":        {},
    }

    for _, a := range args {
        if !strings.HasPrefix(a, "-") {
            // path section reached
            break
        }
        if _, bad := disallowed[a]; bad {
            return fmt.Errorf("disallowed rsync option: %s", a)
        }
        for d := range disallowed {
            if strings.HasPrefix(a, d+"=") {
                return fmt.Errorf("disallowed rsync option: %s", a)
            }
        }
        // check for condensed short flags like -az etc.
        if len(a) > 2 && a[1] != '-' {
            for _, ch := range a[1:] {
                switch ch {
                case 'z', 'e', 'c', 'H', 'S', 'b', 'p', 'g', 'o', 't', 'D', 'L', 'K':
                    return fmt.Errorf("disallowed rsync short option: -%c", ch)
                }
            }
        }
    }
    return nil
}

// canAcceptRsyncArgs is retained for backward-compatibility with existing code
// and the internal test-suite.
func canAcceptRsyncArgs(args []string) bool {
    return sanitizeRsyncArgs(args) == nil
}

