    // Unit-tests sometimes prepend the binary name itself, skip it.
    if len(args) > 0 && args[0] == "rsync" {
        args = args[1:]
    }

    // Only options that allow the client to execute arbitrary commands or to
    // escape the server-side path restrictions are forbidden. Harmless
    // preservation options are now allowed.
    disallowed := map[string]struct{}{
        "--rsync-path":    {}, "--rsh":          {}, "-e":              {}, "--remote-shell":  {},
