func (g *TarGzExtractor) Extract(buffer *bytes.Buffer, targetDir string) error {
	uncompressedStream, err := gzip.NewReader(buffer)
	if err != nil {
		return err
	}
	defer uncompressedStream.Close()

	// Clean the target directory path once for consistent checks
	targetDirClean := filepath.Clean(targetDir)

	if err := os.MkdirAll(targetDirClean, 0755); err != nil {
		return err
	}

	tarReader := tar.NewReader(uncompressedStream)
	for {
		header, err := tarReader.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}

		// --- Path-traversal protection start ---
		name := filepath.Clean(header.Name)

		// Reject absolute paths or traversals trying to break out of targetDir
		if filepath.IsAbs(name) || strings.HasPrefix(name, "..") {
			return errors.Errorf("invalid file path in archive: %s", header.Name)
		}

		path := filepath.Join(targetDirClean, name)

		// Ensure the final path is still within the target directory
		cleanPath := filepath.Clean(path)
		if !strings.HasPrefix(cleanPath, targetDirClean+string(os.PathSeparator)) && cleanPath != targetDirClean {
			return errors.Errorf("illegal file path in archive: %s", header.Name)
		}
		// --- Path-traversal protection end ---

		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(cleanPath, 0755); err != nil {
				return err
			}

		case tar.TypeReg:
			// Ensure parent directory exists
			if err := os.MkdirAll(filepath.Dir(cleanPath), 0755); err != nil {
				return err
			}
			outFile, err := os.OpenFile(cleanPath, os.O_CREATE|os.O_RDWR|os.O_TRUNC, os.FileMode(header.Mode))
			if err != nil {
				return err
			}
			if _, err := io.Copy(outFile, tarReader); err != nil {
				outFile.Close()
				return err
			}
			outFile.Close()

		// Ignore extended headers we do not want to process
		case tar.TypeXGlobalHeader, tar.TypeXHeader:
			continue

		default:
			return errors.Errorf("unknown type: %b in %s", header.Typeflag, header.Name)
		}
	}
	return nil
