func (g *TarGzExtractor) Extract(buffer *bytes.Buffer, targetDir string) error {
    // Create a gzip reader from the in-memory buffer
    gzReader, err := gzip.NewReader(buffer)
    if err != nil {
        return err
    }
    defer gzReader.Close()

    // Clean the target directory once so that all later comparisons are reliable
    cleanTargetDir := filepath.Clean(targetDir)

    // Ensure the target directory exists before we start extracting
    if err := os.MkdirAll(cleanTargetDir, 0755); err != nil {
        return err
    }

    tarReader := tar.NewReader(gzReader)
    for {
        header, err := tarReader.Next()
        if err == io.EOF {
            break // End of archive
        }
        if err != nil {
            return err
        }

        // -------- Path-traversal protection start --------
        // Clean the name inside the archive first
        name := filepath.Clean(header.Name)

        // Reject absolute paths outright
        if filepath.IsAbs(name) {
            return errors.Errorf("invalid absolute path in archive: %s", header.Name)
        }

        // Join the cleaned name with the cleaned target directory
        destPath := filepath.Join(cleanTargetDir, name)
        destPath = filepath.Clean(destPath)

        // Ensure the resulting path is still within the target directory
        if destPath != cleanTargetDir && !strings.HasPrefix(destPath, cleanTargetDir+string(os.PathSeparator)) {
            return errors.Errorf("illegal file path in archive: %s", header.Name)
        }
        // -------- Path-traversal protection end ----------

        switch header.Typeflag {
        case tar.TypeDir:
            // Make the directory (and parents) if required
            if err := os.MkdirAll(destPath, 0755); err != nil && !os.IsExist(err) {
                return err
            }

        case tar.TypeReg:
            // Ensure the file's parent directory exists
            if err := os.MkdirAll(filepath.Dir(destPath), 0755); err != nil {
                return err
            }

            outFile, err := os.OpenFile(destPath, os.O_CREATE|os.O_RDWR|os.O_TRUNC, os.FileMode(header.Mode))
            if err != nil {
                return err
            }

            if _, err := io.Copy(outFile, tarReader); err != nil {
                outFile.Close()
                return err
            }
            outFile.Close()

        // Skip extended headers we do not want to process
        case tar.TypeXGlobalHeader, tar.TypeXHeader:
            continue

        default:
            return errors.Errorf("unknown type: %b in %s", header.Typeflag, header.Name)
        }
    }

    return nil
}

