	c := basicConfig()
	for _, opt := range opts {
		opt(c)
	}
	host, port, err := net.SplitHostPort(hostport)
	if err != nil {
		return "", err
	}

	ip := net.ParseIP(host)
	if ip != nil {
		if ip.IsUnspecified() || (ip.To4() != nil && c.isIPForbidden(ip)) {
			return "", fmt.Errorf("bad ip is detected: %v", ip)
		}
