/* helper to detect dangerous IPv6 addresses */
func isIPv6Forbidden(ip net.IP) bool {
    // ensure we have a 16-byte IPv6 address
    if ip == nil || ip.To16() == nil || ip.To4() != nil {
        return false
    }

    // ::/128 (unspecified) or ::1/128 (loopback)
    if ip.IsUnspecified() || ip.IsLoopback() {
        return true
    }

    // ff00::/8 multicast
    if ip.IsMulticast() {
        return true
    }

    // fc00::/7 unique local
    if ip[0]&0xfe == 0xfc {
        return true
    }

    // fe80::/10 link-local
    if ip[0] == 0xfe && (ip[1]&0xc0) == 0x80 {
        return true
    }

    return false
}

