func redirectTrailingSlash(c *Context) {
	req := c.Request
	p := req.URL.Path

	// Obtain and validate X-Forwarded-Prefix *before* using it.
	if rawPrefix := c.Request.Header.Get("X-Forwarded-Prefix"); rawPrefix != "" {
		// Remove any surrounding white-space that could be injected.
		rawPrefix = strings.TrimSpace(rawPrefix)

		// Accept only prefixes starting with "/" so they are treated as paths,
		// not schemes or hosts. This prevents values such as "http://host" or
		// "//cache-poison" from being used.
		if strings.HasPrefix(rawPrefix, "/") {
			prefix := path.Clean(rawPrefix)

			// After cleaning, the prefix must still be absolute (start with "/")
			// and must not collapse to "." (which represents the current dir).
			if prefix != "." && strings.HasPrefix(prefix, "/") {
				// Reject any remaining traversal attempts or excessively long input.
				if !strings.Contains(prefix, "..") && len(prefix) < 4096 {
					prefix = url.QueryEscape(prefix)
					prefix = strings.ReplaceAll(prefix, "%2F", "/")
					p = prefix + "/" + req.URL.Path
				}
			}
		}
	}

