func sanitizeForwardedPrefix(raw string) string {
    // Trim surrounding white-space first.
    raw = strings.TrimSpace(raw)
    if raw == "" {
        return ""
    }

    // Keep only whitelisted characters.
    var filtered strings.Builder
    filtered.Grow(len(raw))
    for _, r := range raw {
        switch {
        case r == '/' || r == '-' || r == '_':
            filtered.WriteRune(r)
        case r >= '0' && r <= '9':
            filtered.WriteRune(r)
        case r >= 'a' && r <= 'z':
            filtered.WriteRune(r)
        case r >= 'A' && r <= 'Z':
            filtered.WriteRune(r)
        // every other rune is dropped (":", "#", "?", "=", etc.)
        }
    }

    candidate := filtered.String()
    if candidate == "" {
        return ""
    }

    // Collapse duplicate slashes except when they are the two very first runes.
    var collapsed strings.Builder
    var prevSlash bool
    for i, r := range candidate {
        if r == '/' {
            if prevSlash {
                // Allow exactly two leading slashes (index 0 and 1)
                if i == 1 {
                    collapsed.WriteRune(r)
                }
                // skip all other duplicate slashes
                continue
            }
            prevSlash = true
            collapsed.WriteRune(r)
        } else {
            prevSlash = false
            collapsed.WriteRune(r)
        }
    }

    // Enforce a sensible upper bound.
    result := collapsed.String()
    if len(result) > 4096 {
        result = result[:4096]
    }
    return result
}

