function shouldRemoveHeader (header, removeContent, unknownOrigin) {
  // Always strip "host" regardless of origin.
  if (header.length === 4) {
    return util.headerNameToString(header) === 'host'
  }

  // Strip any "content-*" header when requested.
  if (removeContent && util.headerNameToString(header).startsWith('content-')) {
    return true
  }

  // Strip security-sensitive headers when the request is directed to an unknown origin.
  if (unknownOrigin) {
    const len = header.length
    // 13 = 'authorization', 6 = 'cookie', 18 = 'proxy-authorization'
    if (len === 13 || len === 6 || len === 18) {
      const name = util.headerNameToString(header)
      return name === 'authorization' || name === 'proxy-authorization' || name === 'cookie'
    }
  }

  return false
}

