function shouldRemoveHeader (header, removeContent, unknownOrigin) {
  // Convert header name to string once and normalise to lower-case for
  // reliable, case-insensitive comparison.
  const name = util.headerNameToString(header).toLowerCase()

  // Always strip "host" header regardless of origin.
  if (name === 'host') {
    return true
  }

  // Strip any "content-*" header when requested.
  if (removeContent && name.startsWith('content-')) {
    return true
  }

  // Strip security-sensitive headers when the request is directed to an unknown origin.
  if (unknownOrigin && (name === 'authorization' || name === 'proxy-authorization' || name === 'cookie')) {
    return true
  }

  return false
}

