  if (!shouldRedirect) return callback(null, false)
  if (typeof shouldRedirect === 'string') {
    // overridden redirect url
    request.debug('redirect overridden', redirectTo)
    redirectTo = shouldRedirect
  }

  request.debug('redirect to', redirectTo)

  /*
   * SECURITY FIX (CVE-2023-28155)
   * ------------------------------------------------------------------
   * 1. Reject any redirect that points to a non-http(s) scheme.
   * 2. Reject redirects that switch protocol AND hostname unless the
   *    caller explicitly opts-in via `allowInsecureRedirect` or
   *    legacy `allowCrossProtocolRedirects`.
   *
   *    This keeps the library fully backward-compatible for common
   *    http⇆https redirects on the same host while closing the SSRF
   *    bypass vector that involved a server-controlled cross-host
   *    protocol switch.
   */
  var parsedRedirect = url.parse(redirectTo)
  var redirectProtocol = parsedRedirect.protocol
  var currentProtocol = request.uri && request.uri.protocol

  /* 1. Block non-http(s) schemes outright. */
  if (redirectProtocol && redirectProtocol !== 'http:' && redirectProtocol !== 'https:') {
    if (response.resume) response.resume()
    var protoErr = new Error('Unsupported redirect protocol: ' + redirectProtocol)
    protoErr.code = 'ERR_INVALID_PROTOCOL'
    return callback(protoErr)
  }

  /* 2. Disallow protocol+host switch unless explicitly permitted. */
  var protocolChanged = redirectProtocol && currentProtocol && redirectProtocol !== currentProtocol
  var hostChanged = parsedRedirect.hostname && request.uri && parsedRedirect.hostname !== request.uri.hostname
  var allowSwitch = self.allowInsecureRedirect || self.allowCrossProtocolRedirects
  if (protocolChanged && hostChanged && !allowSwitch) {
    if (response.resume) response.resume()
    var switchErr = new Error('Cross-protocol redirect to a different host is disallowed by default (from ' +
      request.uri.hostname + ' to ' + parsedRedirect.hostname + ')')
    switchErr.code = 'ERR_INVALID_PROTOCOL'
    return callback(switchErr)
  }

  // ignore any potential response body.  it cannot possibly be useful
  // to us at this point.
  // response.resume should be defined, but check anyway before calling. Workaround for browserify.
  if (response.resume) {
    response.resume()
  }

  if (self.redirectsFollowed >= self.maxRedirects) {
    return callback(new Error('Exceeded maxRedirects. Probably stuck in a redirect loop ' + request.uri.href))
  }
  self.redirectsFollowed += 1

  if (!isUrl.test(redirectTo)) {
    redirectTo = url.resolve(request.uri.href, redirectTo)
  }

  var uriPrev = request.uri
  request.uri = url.parse(redirectTo)

  // handle the case where we change protocol from https to http or vice versa
  if (request.uri.protocol !== uriPrev.protocol) {
    delete request.agent
  }

  self.redirects.push({ statusCode: response.statusCode, redirectUri: redirectTo })

  if (self.followAllRedirects && request.method !== 'HEAD' &&
    response.statusCode !== 401 && response.statusCode !== 307) {
    request.method = self.followOriginalHttpMethod ? request.method : 'GET'
  }
  // request.method = 'GET' // Force all redirects to use GET || commented out fixes #215
  delete request.src
  delete request.req
  delete request._started
  if (response.statusCode !== 401 && response.statusCode !== 307) {
    // Remove parameters from the previous response, unless this is the second request
    // for a server that requires digest authentication.
    delete request.body
    delete request._form
    if (request.headers) {
      request.removeHeader('host')
      request.removeHeader('content-type')
      request.removeHeader('content-length')
      if (request.uri.hostname !== request.originalHost.split(':')[0]) {
        // Remove authorization if changing hostnames (but not if just
        // changing ports or protocols).  This matches the behavior of curl:
        // https://github.com/bagder/curl/blob/6beb0eee/lib/http.c#L710
        request.removeHeader('authorization')
      }
    }
  }

  if (!self.removeRefererHeader) {
    request.setHeader('referer', uriPrev.href)
  }

  request.emit('redirect')
  request.init()
  callback(null, true)
}

