getInfo: function () {
  var self = this;
  var pdfFilePath = this.pdfFilePath;

  var execFile = require('child_process').execFile; // Safe, no shell
  var path = require('path');

  // Basic validation
  if (typeof pdfFilePath !== 'string' || pdfFilePath.trim() === '') {
    return Promise.reject(new Error('Invalid PDF file path'));
  }

  // Always work with an absolute, canonical path
  var absolutePath = path.resolve(pdfFilePath);

  var promise = new Promise(function (resolve, reject) {
    execFile('pdfinfo', [absolutePath], function (err, stdout, stderr) {
      if (err) {
        return reject({
          message: "Failed to get PDF'S information",
          error: err,
          stdout: stdout,
          stderr: stderr
        });
      }
      return resolve(self.parseGetInfoCommandOutput(stdout));
    });
  });

  return promise;
}

