module.exports = function (msg, silent) {
    const { spawnSync } = require('child_process');
    var commitArgs = ['commit', '--allow-empty', '--no-gpg-sign'];

    // Ensure a default message is always present
    msg = makeDefault(msg);

    if (silent === undefined) {
        silent = true;
    }

    // Build argument list safely (no shell interpretation)
    if (Array.isArray(msg)) {
        if (msg.length) {
            msg.forEach(function (m) {
                m = makeDefault(m);
                commitArgs.push('-m', m);
            });
        } else {
            commitArgs.push('-m', defaultMsg);
        }
    } else {
        commitArgs.push('-m', msg);
    }

    var options = {
        stdio: silent ? 'ignore' : 'inherit',
        shell: false // crucial: run without a shell to avoid injections
    };

    var result = spawnSync('git', commitArgs, options);

    // Propagate errors to keep behaviour explicit
    if (result.error) {
        throw result.error;
    }
};

