function toString(stringify) {
  if (!stringify || 'function' !== typeof stringify) stringify = qs.stringify;

  /*
   * Remove CR/LF from username & password and percent-encode the remaining
   * bytes so that the generated URL never contains raw control characters.
   */
  function sanitizeUserInfo(value) {
    if (typeof value !== 'string') return value;
    return encodeURIComponent(value.replace(/[
]/g, ''));
  }

  var query,
      url      = this,
      protocol = url.protocol;

  if (protocol && protocol.charAt(protocol.length - 1) !== ':') protocol += ':';

  var result = protocol + ((url.protocol && url.slashes) || isSpecial(url.protocol) ? '//' : '');

  /*----------------------------------------------------*/
  /*  User-info                                         */
  /*----------------------------------------------------*/
  if (url.username) {
    result += sanitizeUserInfo(url.username);
    if (url.password) result += ':' + sanitizeUserInfo(url.password);
    result += '@';
  } else if (url.password) {
    result += ':' + sanitizeUserInfo(url.password);
    result += '@';
  } else if (
    url.protocol !== 'file:' &&
    isSpecial(url.protocol) &&
    !url.host &&
    url.pathname !== '/'
  ) {
    // Add back the empty userinfo, otherwise the original invalid URL
    // might be transformed into a valid one with `url.pathname` as host.
    result += '@';
  }

  /*----------------------------------------------------*/
  /*  Host + (empty) port handling                      */
  /*----------------------------------------------------*/
  var hasEmptyPort = Object.prototype.hasOwnProperty.call(url, 'port') && url.port === '';

  result += url.host;
  if (hasEmptyPort) result += ':'; // preserve historic behaviour for explicit empty port

  result += url.pathname;

  /*----------------------------------------------------*/
  /*  Query & hash                                      */
  /*----------------------------------------------------*/
  query = 'object' === typeof url.query ? stringify(url.query) : url.query;
  if (query) result += '?' !== query.charAt(0) ? '?' + query : query;

  if (url.hash) result += url.hash;

  return result;
}

