 * by removing control chars, normalising back-slashes and collapsing
 * protocol-relative URLs.
 * @param {String} loc
 * @returns {String} safe location string
 */
function sanitizeRedirectUrl(loc) {
  if (typeof loc !== 'string') {
    return '/';
  }

  // Trim surrounding whitespace
  var urlStr = loc.trim();

  // Remove CR/LF to prevent response-splitting
  urlStr = urlStr.replace(/[\r\n]/g, '');

  // Convert back-slashes to forward slashes ("http:\\evil.com" → "http://evil.com")
  urlStr = urlStr.replace(/\\+/g, '/');

