file.copy = function copy(srcpath, destpath, options) {
  // --- Security patch: canonicalise paths and block traversal ---
  function sanitizeAbsolute(p) {
    p = String(p);
    // Reject null bytes which can truncate paths in some environments
    if (p.indexOf('\u0000') !== -1) {
      throw new Error('Invalid path: Null byte detected');
    }
    // path.resolve converts to absolute path and removes '../' & './' segments
    return path.resolve(p);
  }

  // Verify that a path stays inside an expected parent directory
  function isPathInside(child, parent) {
    var rel = path.relative(parent, child);
    return rel === '' || (rel && rel.substr(0, 2) !== '..' && !path.isAbsolute(rel));
  }

  var safeSrc  = sanitizeAbsolute(srcpath);
  var safeDest = sanitizeAbsolute(destpath);

  if (file.isDir(safeSrc)) {
    // Copy a directory, recursively.
    // Explicitly create new dest directory.
    file.mkdir(safeDest);
    // Iterate over all sub-files/dirs, recursing.
    fs.readdirSync(safeSrc).forEach(function(filepath) {
      var nextSrc  = path.join(safeSrc, filepath);
      // Resolve destination relative to the current destination dir.
      var nextDest = path.resolve(safeDest, filepath);

      // Abort if the resolved destination escapes the intended directory.
      if (!isPathInside(nextDest, safeDest)) {
        throw new Error('Path traversal detected: ' + nextDest);
      }
      copy(nextSrc, nextDest, options);
    });
  } else {
    // Copy a single file or symbolic link.
    file._copy(safeSrc, safeDest, options);
  }
};

