file.copy = function copy(srcpath, destpath, options) {
  // ---- Security additions: validate paths but keep original semantics ----
  function hasNullByte(p) {
    return String(p).indexOf('\u0000') !== -1;
  }

  function isPathInside(child, parent) {
    var rel = path.relative(parent, child);
    return rel === '' || (rel && rel.substr(0, 2) !== '..' && !path.isAbsolute(rel));
  }

  if (hasNullByte(srcpath) || hasNullByte(destpath)) {
    throw new Error('Invalid path: Null byte detected');
  }

  // Canonical versions used ONLY for security checks – never passed on.
  var resolvedSrc  = path.resolve(srcpath);
  var resolvedDest = path.resolve(destpath);

  if (file.isDir(srcpath)) {
    // Copy a directory, recursively.
    file.mkdir(destpath); // keep original relative/absolute form

    fs.readdirSync(srcpath).forEach(function(filepath) {
      var nextSrc  = path.join(srcpath, filepath);   // original semantics
      var nextDest = path.join(destpath, filepath);  // original semantics

      // Security check – ensure the resolved destination is still inside dest root
      var safeNextDest = path.resolve(resolvedDest, filepath);
      if (!isPathInside(safeNextDest, resolvedDest)) {
        throw new Error('Path traversal detected: ' + safeNextDest);
      }

      copy(nextSrc, nextDest, options);
    });
  } else {
    // Copy a single file or symbolic link.
    file._copy(srcpath, destpath, options);
  }
};

