RedirectableRequest.prototype._processResponse = function (response) {
  // Save the received response for the redirect history feature
  var statusCode = response.statusCode;
  if (this._options.trackRedirects) {
    this._redirects.push({
      url: this._currentUrl,
      headers: response.headers,
      statusCode: statusCode
    });
  }

  // Handle HTTP 3xx responses that contain a Location header
  var location = response.headers.location;
  if (location && this._options.followRedirects !== false &&
      statusCode >= 300 && statusCode < 400) {

    // Abort the current request and discard its body
    abortRequest(this._currentRequest);
    response.destroy();

    // Stop if we exceeded the configured redirect limit
    if (++this._redirectCount > this._options.maxRedirects) {
      this.emit("error", new TooManyRedirectsError());
      return;
    }

    // RFC-compliant method rewriting rules
    if ((statusCode === 301 || statusCode === 302) && this._options.method === "POST" ||
        (statusCode === 303) && !/^(?:GET|HEAD)$/.test(this._options.method)) {
      this._options.method = "GET";
      this._requestBodyBuffers = [];
      removeMatchingHeaders(/^content-/i, this._options.headers);
    }

    // Remove the Host header because the next request might target a new host
    var currentHostHeader = removeMatchingHeaders(/^host$/i, this._options.headers);

    // Build an absolute base URL that we can resolve the redirect against
    var currentUrlParts = url.parse(this._currentUrl);
    var currentHost = currentHostHeader || currentUrlParts.host;
    var baseUrl = /^\w+:/.test(location) ? this._currentUrl :
      url.format(Object.assign(currentUrlParts, { host: currentHost }));

    // Resolve the new absolute redirect URL
    var redirectUrl;
    try {
      redirectUrl = url.resolve(baseUrl, location);
    } catch (cause) {
      this.emit("error", new RedirectionError(cause));
      return;
    }

    // Prepare the next request options
    debug("redirecting to", redirectUrl);
    this._isRedirect = true;
    var redirectUrlParts = url.parse(redirectUrl);
    Object.assign(this._options, redirectUrlParts);

    /*
     * SECURITY FIX: only forward privacy-sensitive headers when the redirect
     * remains on the exact same origin (protocol + hostname + port).
     */
    function getPort(parts) {
      if (parts.port) return parts.port;
      return parts.protocol === "https:" ? "443" : "80";
    }

    var sameOrigin = (currentUrlParts.protocol === redirectUrlParts.protocol) &&
                     (currentUrlParts.hostname === redirectUrlParts.hostname) &&
                     (getPort(currentUrlParts) === getPort(redirectUrlParts));

    if (!sameOrigin) {
      // Strip credentials to avoid leaking them to another origin
      removeMatchingHeaders(/^(authorization|cookie|cookie2)$/i, this._options.headers);
    }

    // Allow user callback to mutate the options before the next request
    if (typeof this._options.beforeRedirect === "function") {
      var responseDetails = { headers: response.headers };
      try {
        this._options.beforeRedirect.call(null, this._options, responseDetails);
      } catch (err) {
        this.emit("error", err);
        return;
      }
      this._sanitizeOptions(this._options);
    }

    // Issue the redirected request
    try {
      this._performRequest();
    } catch (cause) {
      this.emit("error", new RedirectionError(cause));
    }
  } else {
    // Not a redirect – expose the response to the caller
    response.responseUrl = this._currentUrl;
    response.redirects = this._redirects;
    this.emit("response", response);

    // Cleanup
    this._requestBodyBuffers = [];
  }
};

