  const key = k.toLowerCase()

  if (key === 'new_username') {
    newUser.username = req.ctx.query.new_username
  } else if (key === 'org_shortname') {
    /*
     * SECURITY FIX: ensure that only a true system-level admin can move a user to a
     * different organisation.  An organisation admin may *only* keep the user
     * inside their own organisation.
     */
    const requestedOrg   = req.ctx.query.org_shortname
    const requesterRoles = (req.ctx.user && req.ctx.user.roles) || []
    const requesterOrg   = (req.ctx.user && req.ctx.user.org_shortname) || null
    const isSysAdmin     = requesterRoles.includes('system_admin') || requesterRoles.includes('root_admin')

    // If the requester is not a system admin, they can only assign to their own org
    if (!isSysAdmin && requestedOrg !== requesterOrg) {
      /*
       * Throw an error that the upstream middleware can translate into an HTTP 403.
       * Using a plain Error object with explicit status codes avoids relying on a
       * potentially unavailable ctx.throw helper and prevents the 500 response that
       * was previously observed.
       */
      const err       = new Error('Insufficient privileges to transfer user to a different organisation')
      err.status      = 403
      err.statusCode  = 403
      throw err
    }

    newOrgShortName = requestedOrg
    changesRequirePrivilegedRole = true
  } else if (key === 'name.first') {
    newUser.name.first = req.ctx.query['name.first']
  } else if (key === 'name.last') {
    newUser.name.last = req.ctx.query['name.last']
  } else if (key === 'name.middle') {
    newUser.name.middle = req.ctx.query['name.middle']
  } else if (key === 'name.suffix') {
    newUser.name.suffix = req.ctx.query['name.suffix']
  } else if (key === 'name.surname') {
    newUser.name.surname = req.ctx.query['name.surname']
  } else if (key === 'active') {
    newUser.active = req.ctx.query.active
    changesRequirePrivilegedRole = true
  } else if (key === 'active_roles.add') {
    if (Array.isArray(req.ctx.query['active_roles.add'])) {
      req.ctx.query['active_roles.add'].forEach(r => {
        addRoles.push(r)
      })
      changesRequirePrivilegedRole = true
    }
  } else if (key === 'active_roles.remove') {
    if (Array.isArray(req.ctx.query['active_roles.remove'])) {
      req.ctx.query['active_roles.remove'].forEach(r => {
        removeRoles.push(r)
      })
      changesRequirePrivilegedRole = true
    }
  }
})

