def _write(self, contents: dict):
    """Write credentials atomically with restrictive permissions (0600)."""
    LOGGER.debug(f'Writing to {self.path}')
    import os, json  # local import to avoid dependency issues if module top lacks them

    flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
    # Create the file with user read/write only (rw-------).
    fd = os.open(self.path, flags, 0o600)
    try:
        with os.fdopen(fd, 'w') as fp:
            fp.write(json.dumps(contents))
        # Ensure permissions are correct even if the file existed beforehand.
        os.chmod(self.path, 0o600)
    except Exception:
        # If fdopen failed, make sure the raw fd is closed to avoid leaks.
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        raise

