function extractProtocol(address) {
  address = trimLeft(address);

  // SECURITY FIX: Mitigate "backslash poisoning" that can be abused to smuggle
  // an unintended authority component. We only normalise backslashes that
  // appear *before* the first occurrence of an '@' sign. This keeps the
  // original behaviour for non-special schemes while closing the open redirect
  // vector (e.g. "https:\\evil.com\\@trusted.com").
  if (typeof address === 'string' && address.indexOf('\\') !== -1) {
    var atIndex = address.indexOf('@');

    if (atIndex !== -1) {
      // Replace consecutive backslashes with forward slashes in the segment
      // that can potentially become part of the authority section.
      var beforeAt = address.slice(0, atIndex).replace(/\\+/g, '/');
      address = beforeAt + address.slice(atIndex);
    }
  }

  var match     = protocolre.exec(address),
      protocol  = match[1] ? match[1].toLowerCase() : '',
      slashes   = !!(match[2] && match[2].length >= 2),
      rest      = match[2] && match[2].length === 1 ? '/' + match[3] : match[3];

  return {
    protocol: protocol,
    slashes:  slashes,
    rest:     rest
  };
}

