    // ---------------------------------------------------------------------
    baseDir := filepath.Join(r.outputDir, ".git")
    // Resolve the user supplied path against the allowed base directory
    resolvedPath := filepath.Clean(filepath.Join(baseDir, path))

    // Ensure the resolved path is still within the base directory
    if resolvedPath != baseDir && !strings.HasPrefix(resolvedPath, baseDir+string(os.PathSeparator)) {
        return fmt.Errorf("invalid path outside repository: %s", path)
    }

    filePath := resolvedPath

    if r.downloaded[path] {
        return nil
    }
