    relative, err := url.Parse(path)
    if err != nil {
        return err
    }

    absolute := r.baseURL.ResolveReference(relative)
    resp, err := r.http.Get(absolute.String())
    if err != nil {
        return fmt.Errorf("failed to retrieve %s: %w", absolute.String(), err)
    }
