func (hf *Hoverfly) readResponseBodyFile(filePath string) (string, error) {
    // Reject absolute paths immediately (existing behavior)
    if filepath.IsAbs(filePath) {
        return "", fmt.Errorf("bodyFile contains absolute path (%s). only relative is supported", filePath)
    }

    // Canonicalize the provided path to eliminate ../ sequences
    cleanedPath := filepath.Clean(filePath)

    // Construct the final path
    joinedPath := filepath.Join(hf.Cfg.ResponsesBodyFilesPath, cleanedPath)

    // Resolve absolute representations for reliable comparison
    absBase, err := filepath.Abs(hf.Cfg.ResponsesBodyFilesPath)
    if err != nil {
        return "", fmt.Errorf("failed to resolve base path: %w", err)
    }
    absTarget, err := filepath.Abs(joinedPath)
    if err != nil {
        return "", fmt.Errorf("failed to resolve target path: %w", err)
    }

    // Ensure the target stays inside the base directory
    // The trailing separator avoids prefix "/var/app" matching "/var/application".
    baseWithSep := absBase + string(os.PathSeparator)
    targetWithSep := absTarget + string(os.PathSeparator)
    if !strings.HasPrefix(targetWithSep, baseWithSep) {
        return "", fmt.Errorf("bodyFile attempts to access outside the allowed directory (%s)", filePath)
    }

    fileContents, err := ioutil.ReadFile(absTarget)
    if err != nil {
        return "", err
    }

    return string(fileContents[:]), nil
}

