import (
    "fmt"
    "net"
    "strings"
)

// isSafeExternalName ensures that an ExternalName cannot be used to reach
// internal or loopback addresses such as Envoy's admin interface.
// It returns an error when the supplied name is deemed unsafe.
func isSafeExternalName(name string) error {
    if name == "" {
        return nil
    }

    // Explicitly block well-known local hostnames.
    if strings.EqualFold(name, "localhost") {
        return fmt.Errorf("externalName \"%s\" is not allowed", name)
    }

    // If the ExternalName is an IP, verify it is not private / loopback.
    if ip := net.ParseIP(name); ip != nil {
        if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
            return fmt.Errorf("externalName IP %s is not allowed", ip.String())
        }
        return nil
    }

    // For hostnames, block obvious bad ones; deeper DNS inspection is avoided
    // for performance reasons and to keep behaviour deterministic.
    if strings.EqualFold(name, "envoy-admin") {
        return fmt.Errorf("externalName \"%s\" is not allowed", name)
    }
    return nil
}

func (dag *DAG) EnsureService(meta types.NamespacedName, port intstr.IntOrString, cache *KubernetesCache) (*Service, error) {
    svc, svcPort, err := cache.LookupService(meta, port)
    if err != nil {
        return nil, err
    }

    // Validate ExternalName before we do anything else.
    if err := isSafeExternalName(externalName(svc)); err != nil {
        return nil, err
    }

    if dagSvc := dag.GetService(k8s.NamespacedNameOf(svc), svcPort.Port); dagSvc != nil {
        return dagSvc, nil
    }

    dagSvc := &Service{
        Weighted: WeightedService{
            ServiceName:      svc.Name,
            ServiceNamespace: svc.Namespace,
            ServicePort:      svcPort,
            Weight:           1,
        },
        Protocol:           upstreamProtocol(svc, svcPort),
        MaxConnections:     annotation.MaxConnections(svc),
        MaxPendingRequests: annotation.MaxPendingRequests(svc),
        MaxRequests:        annotation.MaxRequests(svc),
        MaxRetries:         annotation.MaxRetries(svc),
        ExternalName:       externalName(svc),
    }
    return dagSvc, nil
}

