func CompileAndAuthorize(actorPermission Permission, toUpdate []Permission) (Permission, error) {
    var permission Permission

    // First pass: ensure the actor explicitly possesses every scope that is
    // being requested. We perform a strict bitwise check so that *only* the
    // scopes the actor explicitly holds are considered – implied scopes are
    // deliberately ignored here.
    for _, update := range toUpdate {
        if update == 0 {
            continue
        }
        // If the actor does not explicitly have every bit in "update", abort.
        if actorPermission&update != update {
            return 0, fmt.Errorf("actor does not have all scopes which are being granted")
        }
        permission |= update
    }

    // Expand the requested permission set with all implied scopes.
    permission = AddImplied(permission)

    // SECURITY CHECK: After adding implied scopes, verify once more – using the
    // *original* actorPermission – that the actor explicitly has every single
    // bit that will ultimately be granted.
    if actorPermission&permission != permission {
        return 0, fmt.Errorf("actor does not have all implied scopes which are being granted")
    }

    return permission, nil
}

