_resolvePath(path = '.') {
  // Normalize user supplied path separators to the current OS standard
  const normalizedInput = String(path).replace(/[\/]+/g, nodePath.sep);

  const clientPath = (() => {
    const p = nodePath.normalize(normalizedInput);
    if (nodePath.isAbsolute(p)) {
      return nodePath.join(p);
    } else {
      return nodePath.join(this.cwd, p);
    }
  })();

  const fsPath = (() => {
    // Resolve the fs path against the server root
    const resolvedPath = nodePath.resolve(this.root, '.' + nodePath.sep, clientPath);

    // Ensure that the resolved path is still within the defined root
    const relative = nodePath.relative(this.root, resolvedPath);
    if (relative && (relative.startsWith('..') || nodePath.isAbsolute(relative))) {
      // Path attempts to escape the user's root, fallback to root directory
      return this.root;
    }

    return resolvedPath;
  })();

  return {
    clientPath,
    fsPath
  };
}

