_resolvePath(path = '.') {
  // 1. Convert the input to string and unify all separators to the platform standard.
  const safeInput = String(path).replace(/[\/]+/g, nodePath.sep);

  const clientPath = (() => {
    // Normalise to collapse '..', '.', and redundant separators.
    const normalised = nodePath.normalize(safeInput);

    // If the user supplied an absolute path, keep it absolute; otherwise,
    // resolve it relative to the current working directory.
    return nodePath.isAbsolute(normalised)
      ? nodePath.join(normalised)
      : nodePath.join(this.cwd, normalised);
  })();

  const fsPath = (() => {
    // Resolve against the user's root directory. Prepending './' prevents
    // path.resolve from discarding the root argument when clientPath is absolute.
    const resolved = nodePath.resolve(this.root, '.' + nodePath.sep, clientPath);

    // Ensure the resolved path is still inside the user's root.
    const relative = nodePath.relative(this.root, resolved);
    if (relative && (relative.startsWith('..') || nodePath.isAbsolute(relative))) {
      // Directory traversal attempt detected – restrict access to the root.
      return this.root;
    }
    return resolved;
  })();

  return { clientPath, fsPath };
}

