func (p *GitLabProvider) EnrichSession(ctx context.Context, s *sessions.SessionState) error {
    // Retrieve user info
    userInfo, err := p.getUserInfo(ctx, s)
    if err != nil {
        return fmt.Errorf("failed to retrieve user info: %v", err)
    }

    // Check if email is verified
    if !p.AllowUnverifiedEmail && !userInfo.EmailVerified {
        return fmt.Errorf("user email is not verified")
    }

    s.User  = userInfo.Username
    s.Email = userInfo.Email

    // Populate the session with ONLY the groups the user actually belongs to.
    p.addGroupsToSession(ctx, s, userInfo)

    p.addProjectsToSession(ctx, s)

    return nil
}

// addGroupsToSession injects the user\'s real GitLab groups into session.Groups
func (p *GitLabProvider) addGroupsToSession(ctx context.Context, s *sessions.SessionState, userInfo *gitlabUserInfo) {
    // Start with a clean slice to avoid leaking stale data between re-authentications
    s.Groups = []string{}

    if userInfo == nil {
        // Defensive guard – nothing to add when userInfo is missing
        return
    }

    // Append each group the user really belongs to
    for _, group := range userInfo.Groups {
        s.Groups = append(s.Groups, fmt.Sprintf("group:%s", group))
    }
}

