  // ------------------------------------------------------------------
  const sanitizePath = (inputPath) => {
    if (typeof inputPath !== 'string')
      throw new TypeError('Path must be a string')

    // Canonicalise to NFC so that different byte sequences collide
    let p = inputPath.normalize('NFC')

    // Convert Windows back-slashes to POSIX style
    p = p.replace(/\\/g, '/')

    // Strip leading drive letters so path is within extraction root
    p = p.replace(/^[a-zA-Z]:\//, '')

    // Remember whether caller explicitly requested a trailing slash
    const hadTrailingSlash = /\/$/.test(p)

    // Collapse duplicate slashes (preserve a single leading slash if present)
    const hasLeadingDouble = p.startsWith('//')
    p = p.replace(/\/{2,}/g, '/')
    if (hasLeadingDouble)
      p = '/' + p

