func (r *Registrator) Certificate(ctx context.Context, in *securityapi.CertificateRequest) (resp *securityapi.CertificateResponse, err error) {
    // ---------------------------------------------------------------------
    // Authorisation: validate the join-token presented by the caller
    // ---------------------------------------------------------------------
    // The worker node must pass the token either via the standard           
    // "authorization: Bearer <token>" header or via a dedicated            
    // "join-token" metadata key.                                           
    md, _ := metadata.FromIncomingContext(ctx)

    var presentedToken string
    if vals := md.Get("authorization"); len(vals) > 0 {
        // Expect the form "Bearer <token>"
        parts := strings.SplitN(vals[0], " ", 2)
        if len(parts) == 2 && strings.EqualFold(parts[0], "Bearer") {
            presentedToken = parts[1]
        }
    }
    if presentedToken == "" {
        // Fallback header name that might be used by older clients
        if vals := md.Get("join-token"); len(vals) > 0 {
            presentedToken = vals[0]
        }
    }

    expectedToken := os.Getenv("TALOS_JOIN_TOKEN")

    // Empty tokens must never be treated as valid.
    if presentedToken == "" || expectedToken == "" || subtle.ConstantTimeCompare([]byte(presentedToken), []byte(expectedToken)) != 1 {
        return nil, status.Error(codes.PermissionDenied, "invalid join token presented for certificate request")
    }
    // ---------------------------------------------------------------------

    // Fetch the cluster CA which is required in any case.
    osRoot, err := safe.StateGet[*secrets.OSRoot](ctx, r.Resources, resource.NewMetadata(secrets.NamespaceName, secrets.OSRootType, secrets.OSRootID, resource.VersionUndefined))
