func (a *AuthenticatorOAuth2Introspection) tokenFromCache(config *AuthenticatorOAuth2IntrospectionConfiguration, token string) (*AuthenticatorOAuth2IntrospectionResult, bool) {
    // Honour per-rule cache switch.
    if !config.Cache.Enabled {
        return nil, false
    }

    // We still use the *raw* token as cache key – every cache hit is re-validated
    // against the current rule in Authenticate, making this safe while keeping
    // cache efficiency.
    item, found := a.tokenCache.Get(token)
    if !found {
        return nil, false
    }

    i, ok := item.(*AuthenticatorOAuth2IntrospectionResult)
    if !ok {
        // Corrupt entry – remove and act as if not found.
        a.tokenCache.Del(token)
        return nil, false
    }

    // Check expiry – result structs store the Unix expiry timestamp in seconds.
    expires := time.Unix(i.Expires, 0)
    if expires.Before(time.Now()) {
        a.tokenCache.Del(token)
        return nil, false
    }

    return i, true
}

