func (a *AuthenticatorOAuth2Introspection) cacheKey(token string, config *AuthenticatorOAuth2IntrospectionConfiguration) string {
    // Build a composite cache key consisting of the token and the
    // authorization-relevant rule parameters. This prevents a token that was
    // introspected for one rule from being re-used with another rule that has
    // different requirements (e.g. other scopes or audience).
    return token + "|" + strings.Join(config.Scopes, " ") + "|" + strings.Join(config.Audience, " ")
}

