    }

    cacheKey := a.cacheKey(token, config)

    item, found := a.tokenCache.Get(cacheKey)
    if !found {
        return nil, false
    }

    i, ok := item.(*AuthenticatorOAuth2IntrospectionResult)
    if !ok {
        // Defensive: remove corrupt entry and behave as if not found.
        a.tokenCache.Del(cacheKey)
        return nil, false
    }

    expires := time.Unix(i.Expires, 0)
    if expires.Before(time.Now()) {
        a.tokenCache.Del(cacheKey)
        return nil, false
    }

    return i, true
}

