patch:
func (rc *resolutionContext) readUserTuple(ctx context.Context, backend storage.TupleBackend) (*openfgapb.TupleKey, error) {
    // validateTuple performs an authorization-model validation on the provided
    // tuple key whenever the current resolutionContext (or one of its embedded
    // fields) exposes a suitable validator. When no validator is available, it
    // falls back to a basic structural sanity check so that obviously
    // malformed tuples are still rejected.
    validateTuple := func(tk *openfgapb.TupleKey) error {
        if tk == nil {
            return fmt.Errorf("tuple is nil")
        }

        // If rc (or one of its embedded structs) implements
        //   ValidateTuple(*openfgapb.TupleKey) error
        // use that for full model-based validation.
        if v, ok := interface{}(rc).(interface{ ValidateTuple(*openfgapb.TupleKey) error }); ok {
            return v.ValidateTuple(tk)
        }

        // Minimal structural validation (fallback).
        if tk.GetObject() == "" || tk.GetRelation() == "" || tk.GetUser() == "" {
            return fmt.Errorf("invalid tuple: object, relation and user must be non-empty")
        }
        return nil
    }

    // ---------------------------------------------------------------------
    // 1. Try to resolve the tuple from contextual tuples first.
    // ---------------------------------------------------------------------
    if tk, ok := rc.contextualTuples.ReadUserTuple(rc.tk); ok {
        if err := validateTuple(tk); err != nil {
            return nil, err
        }
        return tk, nil
    }

    // ---------------------------------------------------------------------
    // 2. Fallback: read from the persistent backend.
    // ---------------------------------------------------------------------
    tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
    if err != nil {
        return nil, err
    }

    // The tuple can legitimately be nil when it does not exist.
    if tuple == nil {
        return nil, nil
    }

    // Validate the backend tuple before returning it.
    if err := validateTuple(tuple.GetKey()); err != nil {
        return nil, err
    }

    return tuple.GetKey(), nil
}

