func (rc *resolutionContext) readUserTuple(ctx context.Context, backend storage.TupleBackend) (*openfgapb.TupleKey, error) {
    // isTupleValid performs a best-effort validation of the provided tuple key.
    // It tries to invoke any available `ValidateTuple` implementation that may
    // live on the resolutionContext itself *or* on an embedded type-system. If
    // neither is present, it falls back to a minimal structural sanity check so
    // obviously malformed tuples are still rejected.
    isTupleValid := func(tk *openfgapb.TupleKey) bool {
        if tk == nil {
            return false
        }

        // 1. Try resolutionContext.ValidateTuple (compile-time safe via
        //    interface assertion).
        if v, ok := interface{}(rc).(interface{ ValidateTuple(*openfgapb.TupleKey) error }); ok {
            return v.ValidateTuple(tk) == nil
        }

        // 2. Try to reflectively discover an embedded `typesystem` (or similar)
        //    that implements `ValidateTuple` so we do not depend on any concrete
        //    field/type names.
        //    This keeps the patch compatible with future refactors while still
        //    ensuring that model-based validation is executed when available.
        rv := reflect.ValueOf(rc)
        if rv.Kind() == reflect.Pointer {
            rv = rv.Elem()
        }
        if rv.IsValid() {
            // Look for a field named `typesystem`, `typeSystem`, or `ts`.
            for _, fieldName := range []string{"typesystem", "typeSystem", "ts"} {
                fv := rv.FieldByName(fieldName)
                if !fv.IsValid() {
                    continue
                }
                // Only attempt the call if the field is addressable and has the
                // desired method.
                if fv.CanInterface() {
                    if method := reflect.ValueOf(fv.Interface()).MethodByName("ValidateTuple"); method.IsValid() {
                        results := method.Call([]reflect.Value{reflect.ValueOf(tk)})
                        if len(results) == 1 {
                            // result should be `error`.
                            if err, ok := results[0].Interface().(error); ok {
                                return err == nil
                            }
                        }
                    }
                }
            }
        }

        // 3. Fallback: minimal structural validation.
        return tk.GetObject() != "" && tk.GetRelation() != "" && tk.GetUser() != ""
    }

    //--------------------------------------------------------------------------
    // 1. Try to resolve the tuple from contextual tuples first.
    //--------------------------------------------------------------------------
    if tk, ok := rc.contextualTuples.ReadUserTuple(rc.tk); ok {
        if !isTupleValid(tk) {
            // Invalid tuples are ignored (treated as "not found").
            return nil, nil
        }
        return tk, nil
    }

    //--------------------------------------------------------------------------
    // 2. Fallback: read from the persistent backend.
    //--------------------------------------------------------------------------
    tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
    if err != nil {
        return nil, err
    }

    // The tuple can legitimately be nil when it does not exist.
    if tuple == nil {
        return nil, nil
    }

    // Validate the backend tuple against the current model before returning it.
    if !isTupleValid(tuple.GetKey()) {
        // Treat an invalid tuple as if it does not exist so that outdated or
        // otherwise unauthorised tuples cannot bypass the authorization model.
        return nil, nil
    }

    return tuple.GetKey(), nil
}

