def lookup_path(
    self, path: str
) -> typing.Tuple[str, typing.Optional[os.stat_result]]:
    """
    Safely resolve *path* against the configured static directories.
    The method prevents directory traversal by normalising the user
    supplied path and ensuring, with os.path.commonpath(), that the final
    resolved path is still located inside one of the allowed directories.
    """
    # 1. Reject NUL byte injection attempts.
    if "\x00" in path:
        return "", None

    # 2. Force the path to be relative and remove any '../' sequences.
    if os.path.isabs(path):
        path = path.lstrip(os.sep)
    path = os.path.normpath(path)

    for directory in self.all_directories:
        # Resolve the base directory once.
        directory_real = os.path.realpath(directory)

        joined_path = os.path.join(directory_real, path)

        # 3. Resolve the final path depending on follow_symlink policy.
        full_path = (
            os.path.abspath(joined_path)
            if self.follow_symlink
            else os.path.realpath(joined_path)
        )

        # 4. Ensure the resolved file is still inside *directory_real*.
        try:
            if os.path.commonpath([full_path, directory_real]) != directory_real:
                continue  # Traversal attempt – skip this directory.
        except ValueError:
            # Raised on Windows if paths reside on different drives.
            continue

        # 5. Stat the file; if it exists, return it.
        try:
            return full_path, os.stat(full_path)
        except (FileNotFoundError, NotADirectoryError):
            continue

    # Nothing found.
    return "", None

