import (
    "bytes"
    "math/big"

    sdk "github.com/cosmos/cosmos-sdk/types"
    authtypes "github.com/cosmos/cosmos-sdk/x/auth/types"

    "github.com/ethereum/go-ethereum/common"

    ethermint "github.com/evmos/ethermint/types"
    sdkerrors "github.com/cosmos/cosmos-sdk/types/errors"
    "github.com/evmos/ethermint/x/evm/types"
)

// DeleteAccount removes an Ethereum account (contract) from the state. It now
// deletes the associated byte-code only when **no other contract** references
// the same CodeHash, preventing inadvertent DoS of siblings that share code.
func (k *Keeper) DeleteAccount(ctx sdk.Context, addr common.Address) error {
    cosmosAddr := sdk.AccAddress(addr.Bytes())
    acct := k.accountKeeper.GetAccount(ctx, cosmosAddr)
    if acct == nil {
        return nil
    }

    // NOTE: only Ethereum accounts (contracts) can be self-destructed
    ethAcct, ok := acct.(ethermint.EthAccountI)
    if !ok {
        return sdkerrors.Wrapf(types.ErrInvalidAccount, "type %T, address %s", acct, addr)
    }

    // ---------------------------------------------------------------------
    // 1. Clear the account balance
    // ---------------------------------------------------------------------
    if err := k.SetBalance(ctx, addr, new(big.Int)); err != nil {
        return err
    }

    // ---------------------------------------------------------------------
    // 2. Delete contract byte-code only when *truly* orphaned
    // ---------------------------------------------------------------------
    codeHashBz := ethAcct.GetCodeHash().Bytes()
    if !bytes.Equal(codeHashBz, types.EmptyCodeHash) {
        stillInUse := false

        // Iterate over *all* accounts to determine if someone else references
        // the same code hash. Stop early when a match is found.
        k.accountKeeper.IterateAccounts(ctx, func(otherAcc authtypes.AccountI) bool {
            if otherAcc == nil {
                return false // continue
            }

            // Skip the account currently being deleted
            if otherAcc.GetAddress().Equals(cosmosAddr) {
                return false // continue
            }

            otherEthAcc, ok := otherAcc.(ethermint.EthAccountI)
            if !ok {
                return false // continue
            }

            if bytes.Equal(otherEthAcc.GetCodeHash().Bytes(), codeHashBz) {
                stillInUse = true // at least one other reference exists
                return true       // break iteration early
            }
            return false // continue
        })

        if !stillInUse {
            // Safe to delete: no other contract depends on this byte-code
            k.SetCode(ctx, codeHashBz, nil)
        }
    }

    // ---------------------------------------------------------------------
    // 3. Clear contract storage
    // ---------------------------------------------------------------------
    k.ForEachStorage(ctx, addr, func(key, _ common.Hash) bool {
        k.SetState(ctx, addr, key, nil)
        return true
    })

    // ---------------------------------------------------------------------
    // 4. Remove the auth account entry itself
    // ---------------------------------------------------------------------
    k.accountKeeper.RemoveAccount(ctx, acct)

    // ---------------------------------------------------------------------
    // 5. Debug log
    // ---------------------------------------------------------------------
    k.Logger(ctx).Debug(
        "account suicided",
        "ethereum-address", addr.Hex(),
        "cosmos-address", cosmosAddr.String(),
    )

    return nil
}

