def _clean_code(self, code: str) -> str:
    """
    Sanitize a user provided code snippet to prevent malicious code execution.

    The method works in three steps:
        1. Parse the code into an AST.
        2. Walk the AST and reject any unsafe construct (dangerous built-ins,
           black-listed modules, dunder attribute access, etc.).
        3. Re-build a cleaned AST that preserves the original, safe logic.

    Args:
        code (str): Python code coming from the user.

    Returns:
        str: A cleaned, executable Python code string.
    """

    # ------------------------------------------------------------------ #
    # 0. Quick rejection for obviously dangerous payloads                #
    # ------------------------------------------------------------------ #
    if "__" in code:  # fast path to block dunder tricks early
        raise ValueError("Access to dunder attributes is not allowed.")

    # ------------------------------------------------------------------ #
    # 1. Parse user code                                                #
    # ------------------------------------------------------------------ #
    try:
        tree = ast.parse(code)
    except SyntaxError as exc:  # propagate a clear error message
        raise ValueError(f"Invalid python code: {exc.msg}") from exc

    # ------------------------------------------------------------------ #
    # 2. Validation helpers & tables                                    #
    # ------------------------------------------------------------------ #
    SAFE_BUILTINS = {
        "len", "range", "sum", "max", "min", "sorted", "list", "dict",
        "set", "tuple", "int", "float", "str", "abs", "round",
        "enumerate", "zip", "map", "filter", "next", "any", "all",
        "slice",
    }

    DISALLOWED_BUILTINS = {
        "exec", "eval", "compile", "open", "input", "globals",
        "locals", "vars", "memoryview", "__import__",
    }

    DISALLOWED_MODULES = {
        "os", "sys", "subprocess", "importlib", "builtins", "socket",
        "pathlib", "shutil", "signal", "ctypes",
    }

    def _get_root_id(attr: ast.Attribute) -> str:
        """Return the left-most name of a chained attribute (e.g. os in os.path.join)."""
        current = attr
        while isinstance(current, ast.Attribute):
            current = current.value
        return current.id if isinstance(current, ast.Name) else ""

    def _validate(node: ast.AST) -> None:
        """Walk the AST and raise ValueError on unsafe constructs."""
        for child in ast.walk(node):
            # --- 2.a Disallowed function calls ------------------------- #
            if isinstance(child, ast.Call):
                func = child.func
                if isinstance(func, ast.Name) and func.id in DISALLOWED_BUILTINS:
                    raise ValueError(f"Use of builtin '{func.id}' is not allowed.")
                if isinstance(func, ast.Attribute):
                    root = _get_root_id(func)
                    if root in DISALLOWED_MODULES:
                        raise ValueError(f"Calls to module '{root}' are not allowed.")

            # --- 2.b Block imports of disallowed modules -------------- #
            if isinstance(child, (ast.Import, ast.ImportFrom)):
                for alias in child.names:
                    if alias.name.split(".")[0] in DISALLOWED_MODULES:
                        raise ValueError(
                            f"Import of module '{alias.name}' is not allowed."
                        )

            # --- 2.c Dunder attributes -------------------------------- #
            if isinstance(child, ast.Attribute) and child.attr.startswith("__"):
                raise ValueError("Access to dunder attributes is not allowed.")

            # --- 2.d Rebinding of disallowed built-ins ---------------- #
            if isinstance(child, ast.Name):
                if child.id in DISALLOWED_BUILTINS and not isinstance(child.ctx, ast.Load):
                    raise ValueError(
                        f"Rebinding of builtin '{child.id}' is not allowed."
                    )

    _validate(tree)

    # ------------------------------------------------------------------ #
    # 3. Original sanitisation logic                                    #
    # ------------------------------------------------------------------ #
    new_body = []

    # clear recent optional dependencies
    self._additional_dependencies = []

    for node in tree.body:
        # keep using the existing import whitelist logic
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            self._check_imports(node)
            continue
        if self._is_df_overwrite(node):
            continue
        new_body.append(node)

    # ast.Module signature differs across Python versions
    try:
        new_tree = ast.Module(body=new_body, type_ignores=[])
    except TypeError:  # pragma: no cover (Py < 3.8)
        new_tree = ast.Module(body=new_body)

    # Turn the validated AST back into source code
    return (
        astor.to_source(new_tree, pretty_source=lambda src: "".join(src)).strip()
    )

