    if tokens[0] == "ref:":
        return (None, tokens[1])

    # Direct commit hash?
    if repo.re_hexsha_only.match(tokens[0]):
        return (tokens[0], None)

    raise ValueError(f"Failed to parse reference information from {ref_path!r}")

