    """Return (sha, target_ref_path) for *ref_path*.

    sha is the commit hash the reference points to or ``None`` if *ref_path*
    itself is a symbolic reference. *target_ref_path* is the symbolic
    reference we point to or ``None`` if *ref_path* directly stores a sha.
    """
    if ref_path is None:
        raise ValueError("Reference path cannot be None")

    # Validate the user-supplied reference name first.
    cls._check_ref_name_valid(str(ref_path))

    repodir = _git_dir(repo, ref_path)

    # Build the absolute path and make sure it stays inside *repodir*.
    full_path = os.path.abspath(os.path.join(repodir, str(ref_path)))
    repodir_abs = os.path.abspath(repodir)
    if not (full_path == repodir_abs or full_path.startswith(repodir_abs + os.sep)):
        raise ValueError(f"Reference '{ref_path}' resolves outside of repository directory")

    tokens: Union[None, List[str], Tuple[str, str]] = None
    try:
        with open(full_path, "rt", encoding="UTF-8") as fp:
            value = fp.read().rstrip()
        # Split on arbitrary whitespace to handle lines like:
        # 60b64ef9...                branch 'master' of git-server:/path/to/repo
        tokens = value.split()
        assert len(tokens) != 0
    except OSError:
        # Probably packed; look it up in the packed-refs file instead. A
        # packed entry cannot be a symbolic ref, so we only expect a sha.
        for sha, path in cls._iter_packed_refs(repo):
            if path != ref_path:
                continue
            tokens = sha, path  # sha will be used
            break
    # END packed-refs lookup

    if tokens is None:
        raise ValueError(f"Reference at {ref_path!r} does not exist")

    # Symbolic reference?
    if tokens[0] == "ref:":
        return (None, tokens[1])

    # Direct commit hash?
    if repo.re_hexsha_only.match(tokens[0]):
        return (tokens[0], None)

    raise ValueError(f"Failed to parse reference information from {ref_path!r}")

