var BAD_PROTOCOLS    = [ 'vbscript', 'javascript', 'file', 'data' ];

// Whitelist for safe data URI media types (case-insensitive)
var DATA_IMAGE_MIME_PREFIXES = [
  'image/png',
  'image/gif',
  'image/jpeg',
  'image/webp',
  'image/svg+xml'
];

function validateLink(url) {
  // url should be normalized at this point, and existing entities are decoded
  //
  var str = url.trim().toLowerCase();

  // Special handling for `data:` URIs - allow only specific, safe image mime types
  if (str.slice(0, 5) === 'data:') {
    var comma = str.indexOf(',');
    if (comma !== -1) {
      var mime = str.slice(5, comma).split(';')[0];
      if (DATA_IMAGE_MIME_PREFIXES.indexOf(mime) >= 0) {
        return true; // safe data:image/* URI
      }
    }
    return false; // any other data:* URI is considered unsafe
  }

  if (str.indexOf(':') >= 0) {
    var protocol = str.split(':')[0];
    if (BAD_PROTOCOLS.indexOf(protocol) >= 0) {
      return false;
    }
  }
  return true;
}

