    // 2. Strictly validate that the user supplied path cannot alter host.
    // ---------------------------------------------------------------------
    validateRelativePath := func(p string) error {
        if p == "" {
            return nil // empty path is allowed – will resolve to base path
        }
        if !strings.HasPrefix(p, "/") {
            return fmt.Errorf("query.Path must start with '/' (got %q)", p)
        }
        if strings.HasPrefix(p, "//") {
            return fmt.Errorf("query.Path must not start with '//' (network-path reference)")
        }
