            return fmt.Errorf("query.Path contains forbidden characters")
        }
        ref, err := url.Parse(p)
        if err != nil {
            return err
        }
        if ref.Scheme != "" || ref.Host != "" {
            return fmt.Errorf("query.Path must be a relative path without scheme or host")
        }
        return nil
    }
    if err := validateRelativePath(query.Path); err != nil {
        return nil, err
    }

