func (r ResourceServer) ValidateAccessToken(ctx context.Context, expectedAudience, tokenStr string) (interfaces.IdentityContext, error) {
    // Step 1: validate signature
    raw, err := r.signatureVerifier.VerifySignature(ctx, tokenStr)
    if err != nil {
        return nil, err
    }

    // Step 2: unmarshal claims
    claimsRaw := map[string]interface{}{}
    if err = json.Unmarshal(raw, &claimsRaw); err != nil {
        return nil, fmt.Errorf("failed to unmarshal user info claim into UserInfo type. Error: %w", err)
    }

    // --------------------------------------------------------------------
    // Step 3: temporal claim validation (exp, nbf, iat)
    // --------------------------------------------------------------------
    now := time.Now().Unix()

    // ----- exp (required) -----
    expVal, ok := claimsRaw["exp"]
    if !ok {
        return nil, fmt.Errorf("token missing exp claim")
    }
    expUnix, err := numericDateToInt64(expVal)
    if err != nil {
        return nil, fmt.Errorf("invalid exp claim: %w", err)
    }
    if now >= expUnix {
        return nil, fmt.Errorf("token has expired")
    }

    // ----- nbf (optional) -----
    if nbfVal, ok := claimsRaw["nbf"]; ok {
        nbfUnix, err := numericDateToInt64(nbfVal)
        if err != nil {
            return nil, fmt.Errorf("invalid nbf claim: %w", err)
        }
        if now < nbfUnix {
            return nil, fmt.Errorf("token not valid yet")
        }
    }

    // ----- iat sanity check (optional) -----
    if iatVal, ok := claimsRaw["iat"]; ok {
        iatUnix, err := numericDateToInt64(iatVal)
        if err == nil {
            // allow up to 5 minutes clock skew
            if iatUnix-now > 300 {
                return nil, fmt.Errorf("token issued-at time is in the future")
            }
        }
    }

    // Step 4: audience & any remaining validation
    return verifyClaims(sets.NewString(append(r.allowedAudience, expectedAudience)...), claimsRaw)
}

// numericDateToInt64 converts the various JSON number representations (float64, json.Number, etc.)
// used by Go's standard library into a consistent int64 UNIX timestamp.
func numericDateToInt64(v interface{}) (int64, error) {
    switch t := v.(type) {
    case float64:
        return int64(t), nil
    case int64:
        return t, nil
    case int:
        return int64(t), nil
    case json.Number:
        return t.Int64()
    default:
        return 0, fmt.Errorf("unsupported numeric date type %T", v)
    }
}

