func buildContextualTupleHash(tuples []*openfgav1.TupleKey) string {
    if len(tuples) == 0 {
        return ""
    }

    // Convert to []string
    keys := make([]string, len(tuples))
    for i, t := range tuples {
        keys[i] = t.String()
    }

    // Simple insertion sort for deterministic ordering (no extra imports).
    for i := 1; i < len(keys); i++ {
        for j := i; j > 0 && keys[j] < keys[j-1]; j-- {
            keys[j], keys[j-1] = keys[j-1], keys[j]
        }
