def create_shelf():
    """Create a new shelf, enforcing proper authorisation for *public* shelves."""
    # Local imports placed here to avoid polluting module namespace and to
    # guarantee availability, even when the module is re-loaded in tests.
    from flask import abort, request, redirect, url_for, flash
    from flask_login import current_user

    # Instantiate a new shelf object as before
    shelf = ub.Shelf()

    # ------------------------------------------------------------------
    # SECURITY CHECK (executed only on POST – GET merely renders the form)
    # ------------------------------------------------------------------
    if request.method == "POST":
        # In Calibre-Web a shelf is considered *public* by default when the
        # "public" field is missing or evaluates to a truthy value.
        requested_public = True  # assume public unless proven otherwise
        if "public" in request.form:
            val = str(request.form.get("public", "")).strip().lower()
            requested_public = val not in ("", "0", "false", "off")

        if requested_public:
            def _user_can_create_public(user):
                """Return True if *user* possesses a recognised public-shelf flag."""
                for attr in ("can_create_public_shelf", "is_admin", "admin"):
                    if hasattr(user, attr):
                        value = getattr(user, attr)
                        try:
                            value = value() if callable(value) else value
                        except TypeError:
                            # Attribute is callable but expects params – treat as False.
                            value = False
                        if bool(value):
                            return True
                return False

            if not _user_can_create_public(current_user):
                # Preserve original UX: notify and redirect instead of hard 403.
                flash(_(u"You are not allowed to create public shelves."), "error")
                return redirect(url_for("web.index"))

    # Continue with the original flow (authorised or private shelf creation)
    return create_edit_shelf(shelf, page_title=_(u"Create a Shelf"), page="shelfcreate")

