// normalizeDomain returns the canonical representation of a domain name.
// It lower-cases the input and removes any trailing dots so that
// different textual representations of the same host are treated equally.
func normalizeDomain(d string) string {
    // RFC 4343: domain names are case-insensitive; a trailing dot denotes the root zone.
    return strings.TrimRight(strings.ToLower(d), ".")
}

func hostMatchesGlob(host string, domainGlob string) bool {
    // Canonicalise both operands to avoid case and trailing-dot bypasses.
    host = normalizeDomain(host)
    domainGlob = normalizeDomain(domainGlob)

    if domainGlob != "" && domainGlob[0] == '*' {
        suffix := domainGlob[1:]
        return strings.HasSuffix(host, suffix)
    }
    return host == domainGlob
}

