func RequireSignedJWT(ctx context.Context, key []byte) error {
    // If no shared key is configured, skip JWT validation.
    if len(key) == 0 {
        return nil
    }

    rawjwt, ok := JWTFromGRPCRequest(ctx)
    if !ok {
        return status.Error(codes.Unauthenticated, "unauthenticated")
    }

    // Perform full validation (signature, expiry, audience …).
    if err := validateJWT(rawjwt, key, "pomerium-databroker"); err != nil {
        // Differentiate between an invalid token and an unauthorized one.
        if strings.HasPrefix(err.Error(), "unauthorized") {
            return status.Errorf(codes.PermissionDenied, err.Error())
        }
        return status.Errorf(codes.Unauthenticated, err.Error())
    }

    return nil
}

// validateJWT fully validates a signed JWT. The optional third parameter
// allows tests to specify a custom audience. It returns an error describing
// why the token is invalid/unauthorized or nil if the token is valid.
func validateJWT(rawjwt string, key []byte, audience ...string) error {
    tok, err := jwt.ParseSigned(rawjwt)
    if err != nil {
        return fmt.Errorf("invalid JWT: %w", err)
    }

    // Decode into standard registered claims so Validate can be used.
    var claims jwt.Claims
    if err := tok.Claims(key, &claims); err != nil {
        return fmt.Errorf("invalid JWT: %w", err)
    }

    // Default audience expected by databroker; override if caller supplied one.
    aud := "pomerium-databroker"
    if len(audience) > 0 && audience[0] != "" {
        aud = audience[0]
    }

    expected := jwt.Expected{
        Time:     time.Now(),
        Audience: jwt.Audience{aud},
    }
    if err := claims.Validate(expected); err != nil {
        return fmt.Errorf("unauthorized JWT: %w", err)
    }

    return nil
}

