func RequireSignedJWT(ctx context.Context, key []byte) error {
	if len(key) > 0 {
		rawjwt, ok := JWTFromGRPCRequest(ctx)
		if !ok {
			return status.Error(codes.Unauthenticated, "unauthenticated")
		}

		if err := validateJWT(rawjwt, key); err != nil {
			log.Ctx(ctx).Debug().Err(err).Msg("rejected gRPC request due to invalid JWT")
			return status.Error(codes.Unauthenticated, "invalid JWT")
		}
	}
	return nil
}

func validateJWT(rawjwt string, key []byte) error {
	tok, err := jwt.ParseSigned(rawjwt)
	if err != nil {
		return err
	}

	var claims map[string]*jwt.NumericDate
	err = tok.Claims(key, &claims)
	if err != nil {
		return err
	} else if len(claims) != 1 || claims["exp"] == nil {
		return fmt.Errorf("expected exactly one claim (exp)")
	}

	if t := claims["exp"].Time(); time.Now().After(t) {
		return fmt.Errorf("JWT expired at %s", t.Format(time.DateTime))
	}
	return nil
}

patch:
package grpcutil

import (
    "context"
    "errors"
    "fmt"
    "time"

    "github.com/square/go-jose/v3/jwt"
    "google.golang.org/grpc/codes"
    "google.golang.org/grpc/status"
)

// RequireSignedJWT enforces that an incoming gRPC request carries a
// valid, authorised JWT in its metadata.  The token must be signed with
// the shared key *and* contain the correct audience as well as a valid
// expiry.
func RequireSignedJWT(ctx context.Context, key []byte) error {
    // Preserve backwards-compatible behaviour for single-binary or
    // self-signed deployments that do not configure a shared key.
    if len(key) == 0 {
        return nil
    }

    rawjwt, ok := JWTFromGRPCRequest(ctx)
    if !ok {
        return status.Error(codes.Unauthenticated, "unauthenticated")
    }

    // Re-use the helper so unit tests stay intact.
    if err := validateJWT(rawjwt, key); err != nil {
        // Distinguish between authentication and authorisation errors.
        if errors.Is(err, errUnauthorizedJWT) {
            return status.Error(codes.PermissionDenied, err.Error())
        }
        return status.Error(codes.Unauthenticated, err.Error())
    }

    return nil
}

// Sentinel errors so callers (and the wrapper above) can differentiate
// between *invalid* and *unauthorised* tokens.
var (
    errInvalidJWT      = errors.New("invalid JWT")
    errUnauthorizedJWT = errors.New("unauthorized JWT")
)

// validateJWT parses, verifies the signature, and validates the
// standard claims of a JWT.  It returns errUnauthorizedJWT when the
// token is correctly signed but fails semantic checks (e.g. wrong
// audience, expired).
func validateJWT(rawjwt string, key []byte) error {
    // Empty key => nothing to validate (already handled by caller, but
    // keep for standalone use in unit tests).
    if len(key) == 0 {
        return nil
    }

    // 1. Parse and verify signature.
    tok, err := jwt.ParseSigned(rawjwt)
    if err != nil {
        return fmt.Errorf("%w: %v", errInvalidJWT, err)
    }

    // 2. Decode into standard claims so we can run full validation.
    var claims jwt.Claims
    if err := tok.Claims(key, &claims); err != nil {
        return fmt.Errorf("%w: %v", errInvalidJWT, err)
    }

    // 3. Validate all registered claims (audience, expiry, etc.).
    expected := jwt.Expected{
        Time:     time.Now(),
        Audience: jwt.Audience{"pomerium-databroker"},
    }
    if err := claims.Validate(expected); err != nil {
        // Token is well-formed and signed but not authorised for this API.
        return fmt.Errorf("%w: %v", errUnauthorizedJWT, err)
    }

    return nil
}

