    opts := updateServiceAccountOpts{
        secretKey:     updateReq.NewSecretKey,
        status:        updateReq.NewStatus,
        name:          updateReq.NewName,
        description:   updateReq.NewDescription,
        expiration:    updateReq.NewExpiration,
