func wrapDirector(d func(*http.Request)) func(req *http.Request) {
    return func(req *http.Request) {
        d(req)
        PrepareProxyRequest(req)

        // Strip sensitive Grafana authentication credentials before forwarding
        sanitizeRequestHeaders(req)

        // Clear Origin and Referer to avoid CORS issues
        req.Header.Del("Origin")
        req.Header.Del("Referer")
    }
}

// sanitizeRequestHeaders removes headers that may expose Grafana credentials
// to third-party plugin back-ends.
func sanitizeRequestHeaders(req *http.Request) {
    for _, h := range []string{"Authorization", "Cookie", "Set-Cookie", "X-Grafana-User", "X-Grafana-Org-Id"} {
        req.Header.Del(h)
    }
}

