function escapeShellArg(arg) {
  // Convert value to string early to avoid unexpected issues
  if (arg === null || arg === undefined) {
    return "''";
  }

  const str = String(arg);

  /*
   * Inside a single-quoted string, the only character that needs special
   * treatment is another single quote. The standard and safest POSIX way to
   * escape it is: close the quote, add an escaped single quote, and reopen the
   * quote. Example:  foo'bar  →  'foo'\''bar'
   */
  const escaped = str.replace(/'/g, "'\\''");

  // Wrap the entire argument in single quotes so the shell treats it literally
  return `'${escaped}'`;
}

