function escapeShellArg(arg) {
  // Treat null or undefined consistently
  if (arg === null || arg === undefined) {
    return '';
  }

  // Ensure the value is a string for consistent processing
  const str = String(arg);

  /*
   * Step 1: Strip ASCII control characters (\x00-\x1F and \x7F). These
   *         characters can act as argument delimiters in many shells and
   *         therefore open the door for argument injection (e.g. NULL byte
   *         or newline characters).
   * Step 2: Escape single quotes using the standard POSIX pattern so the
   *         resulting string can be embedded safely inside a single-quoted
   *         context.
   */
  const withoutControlChars = str.replace(/[\u0000-\u001F\u007F]/g, '');

  return withoutControlChars.replace(/'/g, "'\\''");
}

