        if err != nil {
            ctx.Logger.WithError(err).Error("Failed to get session provider during 1FA attempt")
            respondUnauthorized(ctx, messageAuthenticationFailed)
            return
        }

        userSession, err := provider.GetSession(ctx.RequestCtx)
        if err != nil {
            ctx.Logger.Errorf("%s", err)
            respondUnauthorized(ctx, messageAuthenticationFailed)
            return
        }

        newSession := provider.NewDefaultUserSession()

        // Reset all values from previous session except OIDC workflow before regenerating the cookie.
        if err = ctx.SaveSession(newSession); err != nil {
            ctx.Logger.WithError(err).Errorf(logFmtErrSessionReset, regulation.AuthType1FA, canonicalUsername)
            respondUnauthorized(ctx, messageAuthenticationFailed)
            return
        }

        if err = ctx.RegenerateSession(); err != nil {
            ctx.Logger.WithError(err).Errorf(logFmtErrSessionRegenerate, regulation.AuthType1FA, canonicalUsername)
            respondUnauthorized(ctx, messageAuthenticationFailed)
            return
        }

