                respondUnauthorized(ctx, messageAuthenticationFailed)
                return
            }
        }

        // Get the details of the given user from the user provider.
        userDetails, err := ctx.Providers.UserProvider.GetDetails(canonicalUsername)
        if err != nil {
            ctx.Logger.WithError(err).Errorf(logFmtErrObtainProfileDetails, regulation.AuthType1FA, canonicalUsername)
            respondUnauthorized(ctx, messageAuthenticationFailed)
            return
        }

        ctx.Logger.Tracef(logFmtTraceProfileDetails, canonicalUsername, userDetails.Groups, userDetails.Emails)

        userSession.SetOneFactor(ctx.Clock.Now(), userDetails, keepMeLoggedIn)

        if ctx.Configuration.AuthenticationBackend.RefreshInterval.Update() {
            userSession.RefreshTTL = ctx.Clock.Now().Add(ctx.Configuration.AuthenticationBackend.RefreshInterval.Value())
        }

        if err = ctx.SaveSession(userSession); err != nil {
            ctx.Logger.WithError(err).Errorf(logFmtErrSessionSave, "updated profile", regulation.AuthType1FA, logFmtActionAuthentication, canonicalUsername)
            respondUnauthorized(ctx, messageAuthenticationFailed)
            return
        }

        successful = true

        if bodyJSON.Workflow == workflowOpenIDConnect {
            handleOIDCWorkflowResponse(ctx, &userSession, bodyJSON.TargetURL, bodyJSON.WorkflowID)
        } else {
            Handle1FAResponse(ctx, bodyJSON.TargetURL, bodyJSON.RequestMethod, userSession.Username, userSession.Groups)
        }
    }
}

