func Init(ds model.DataStore) {
    once.Do(func() {
        log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)

        // 1. Prefer secret provided via environment variable (not persisted anywhere)
        secret := os.Getenv("NAVIDROME_JWT_SECRET")

        // 2. If not set, fall back to a legacy value stored in the DB (if any).
        //    Regardless of whether we obtain it successfully, delete it so that
        //    no clear-text copy remains on disk.
        if secret == "" && ds != nil {
            var err error
            secret, err = ds.Property(context.TODO()).Get(consts.JWTSecretKey)
            if err != nil {
                log.Warn("Could not retrieve legacy JWT secret from DB", "error", err)
            }
            if delErr := ds.Property(context.TODO()).Delete(consts.JWTSecretKey); delErr != nil {
                log.Warn("Could not delete legacy JWT secret from DB", "error", delErr)
            }
        }

        // 3. If we still do not have a secret, generate a volatile one.
        if secret == "" {
            secret = uuid.NewString()
        }

        Secret = []byte(secret)
        TokenAuth = jwtauth.New("HS256", Secret, nil)
    })
}

