    "context"
    "os"
    "sync"

    "github.com/go-chi/jwtauth/v5"
    "github.com/google/uuid"

    "github.com/navidrome/navidrome/conf"
    "github.com/navidrome/navidrome/core/consts"
    "github.com/navidrome/navidrome/core/log"
    "github.com/navidrome/navidrome/model"
)

var (
    TokenAuth *jwtauth.JWTAuth
    Secret    []byte
    once      sync.Once
)

// Init initialises JWT handling without storing cleartext secret on disk or database.
// Order of preference:
// 1. Use secret from environment variable NAVIDROME_JWT_SECRET.
// 2. Use legacy secret stored in the DB (if present) and then delete it.
// 3. Generate a random in-memory secret.
func Init(ds model.DataStore) {
    once.Do(func() {
        log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)

        // 1. Prefer a secret provided through environment variable.
        secret := os.Getenv("NAVIDROME_JWT_SECRET")

        // 2. Fallback to legacy secret stored in DB (if any), then delete it
        if secret == "" && ds != nil {
            var err error
            secret, err = ds.Property(context.TODO()).Get(consts.JWTSecretKey)
            if err != nil {
                log.Warn("Could not retrieve legacy JWT secret from DB", "error", err)
            }
            if delErr := ds.Property(context.TODO()).Delete(consts.JWTSecretKey); delErr != nil {
                log.Warn("Could not delete legacy JWT secret from DB", "error", delErr)
            }
        }

        // 3. Generate an in-memory secret when none is available
        if secret == "" {
            secret = uuid.NewString()
        }

        Secret = []byte(secret)
        TokenAuth = jwtauth.New("HS256", Secret, nil)
    })
}

