var disallowed = regexp.MustCompile(`[-_ .]`)

func lookupPreprocess(s string) string {
	// Normalize first so that compatibility characters (e.g., U+FE4D) are
	// decomposed to their ASCII equivalents, ensuring they are removed by the
	// regex below and cannot bypass the filter.
	normalized := norm.NFKD.String(s)
	cleaned := disallowed.ReplaceAllString(normalized, "")
	return strings.ToLower(cleaned)
}

