func fromOrig(c common, orig interface{}) (Manifest, error) {
	var mt string
	var m Manifest
	origDigest := c.desc.Digest // save pinned digest for verification

	mj, err := json.Marshal(orig)
	if err != nil {
		return nil, err
	}
	c.manifSet = true
	if len(c.rawBody) == 0 {
		c.rawBody = mj
	}

	// For unsigned manifests: calculate and verify digest before storing it
	if _, ok := orig.(schema1.SignedManifest); !ok {
		computedDigest := c.desc.DigestAlgo().FromBytes(mj)
		if origDigest != "" && origDigest != computedDigest {
			return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", origDigest, computedDigest)
		}
		c.desc.Digest = computedDigest
	}

	if c.desc.Size == 0 {
		c.desc.Size = int64(len(mj))
	}

