func New(opts ...Opts) (Manifest, error) {
    mc := manifestConfig{}
    for _, opt := range opts {
        opt(&mc)
    }
    c := common{
        r:         mc.r,
        desc:      mc.desc,
        rawBody:   mc.raw,
        rawHeader: mc.header,
    }
    // extract fields from header where available
    if mc.header != nil {
        if c.desc.MediaType == "" {
            c.desc.MediaType = mediatype.Base(mc.header.Get("Content-Type"))
        }
        if c.desc.Size == 0 {
            cl, _ := strconv.Atoi(mc.header.Get("Content-Length"))
            c.desc.Size = int64(cl)
        }
        if c.desc.Digest == "" {
            c.desc.Digest, _ = digest.Parse(mc.header.Get("Docker-Content-Digest"))
        }
        c.setRateLimit(mc.header)
    }
    // If the registry did not return a digest header, but the reference was "name@digest",
    // propagate that digest into the descriptor so that later verification succeeds.
    if c.desc.Digest == "" && c.r.Digest != "" {
        if dParsed, err := digest.Parse(c.r.Digest); err == nil {
            c.desc.Digest = dParsed
        }
    }

    if mc.orig != nil {
        return fromOrig(c, mc.orig)
    }
    return fromCommon(c)
}

