func fromOrig(c common, orig interface{}) (Manifest, error) {
    var mt string
    var m Manifest

    // helper to pick the first non-empty digest (for error msgs)
    firstNonEmpty := func(vals ...digest.Digest) digest.Digest {
        for _, v := range vals {
            if v != "" {
                return v
            }
        }
        return ""
    }

    // capture authoritative digests
    origDescDigest := c.desc.Digest
    var origRefDigest digest.Digest
    if c.r.Digest != "" {
        origRefDigest, _ = digest.Parse(c.r.Digest)
    }

    mj, err := json.Marshal(orig)
    if err != nil {
        return nil, err
    }
    c.manifSet = true
    if len(c.rawBody) == 0 {
        c.rawBody = mj
    }

    // unsigned manifests: calculate and verify digest
    if _, ok := orig.(schema1.SignedManifest); !ok {
        computedDigest := c.desc.DigestAlgo().FromBytes(mj)
        if (origDescDigest != "" && origDescDigest != computedDigest) ||
            (origRefDigest != "" && origRefDigest != computedDigest) {
            return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", firstNonEmpty(origDescDigest, origRefDigest), computedDigest)
        }
        c.desc.Digest = computedDigest
    }

    if c.desc.Size == 0 {
        c.desc.Size = int64(len(mj))
    }

    // create manifest based on type
    switch mOrig := orig.(type) {
    case schema1.Manifest:
        mt = mOrig.MediaType
        c.desc.MediaType = mediatype.Docker1Manifest
        m = &docker1Manifest{common: c, Manifest: mOrig}
    case schema1.SignedManifest:
        mt = mOrig.MediaType
        c.desc.MediaType = mediatype.Docker1ManifestSigned
        computedDigest := c.desc.DigestAlgo().FromBytes(mOrig.Canonical)
        if (origDescDigest != "" && origDescDigest != computedDigest) ||
            (origRefDigest != "" && origRefDigest != computedDigest) {
            return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", firstNonEmpty(origDescDigest, origRefDigest), computedDigest)
        }
        c.desc.Digest = computedDigest
        m = &docker1SignedManifest{common: c, SignedManifest: mOrig}
    case schema2.Manifest:
        mt = mOrig.MediaType
        c.desc.MediaType = mediatype.Docker2Manifest
        m = &docker2Manifest{common: c, Manifest: mOrig}
    case schema2.ManifestList:
        mt = mOrig.MediaType
        c.desc.MediaType = mediatype.Docker2ManifestList
        m = &docker2ManifestList{common: c, ManifestList: mOrig}
    case v1.Manifest:
        mt = mOrig.MediaType
        c.desc.MediaType = mediatype.OCI1Manifest
        m = &oci1Manifest{common: c, Manifest: mOrig}
    case v1.Index:
        mt = mOrig.MediaType
        c.desc.MediaType = mediatype.OCI1ManifestList
        m = &oci1Index{common: c, Index: mOrig}
    case v1.ArtifactManifest:
        mt = mOrig.MediaType
        c.desc.MediaType = mediatype.OCI1Artifact
        m = &oci1Artifact{common: c, ArtifactManifest: mOrig}
    default:
        return nil, fmt.Errorf("unsupported type to convert to a manifest: %T", orig)
    }

    // verify media type
    err = verifyMT(c.desc.MediaType, mt)
    if err != nil {
        return nil, err
    }

    // final consistency check
    if (origDescDigest != "" && origDescDigest != c.desc.Digest) ||
        (origRefDigest != "" && origRefDigest != c.desc.Digest) {
        return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", firstNonEmpty(origDescDigest, origRefDigest), c.desc.Digest)
    }

    return m, nil
}

