// Engine represents the Django template engine wrapper.
type Engine struct {
    /* existing fields ... */

    // AutoEscape determines whether template output is automatically
    // escaped before being sent to the client.  The secure default is
    // enabled unless the user explicitly disables it via SetAutoEscape.
    AutoEscape bool

    // autoEscapeSet is true after the user has explicitly called
    // SetAutoEscape; it lets us distinguish the secure default from an
    // intentional override.
    autoEscapeSet bool
}

// SetAutoEscape allows callers to enable or disable automatic escaping.
func (e *Engine) SetAutoEscape(enable bool) {
    e.AutoEscape = enable
    e.autoEscapeSet = true
}

