// sanitizeSecrets walks any struct and masks string fields whose names suggest they
// contain sensitive information ("secret", "password", etc.). This generic approach
// prevents accidental leaks of newly-added secrets without requiring future code changes.
func sanitizeSecrets(target interface{}) {
    visited := map[uintptr]bool{}

    var walk func(reflect.Value)
    walk = func(v reflect.Value) {
        if !v.IsValid() {
            return
        }

        // Resolve pointers and interfaces first
        for v.Kind() == reflect.Interface || v.Kind() == reflect.Ptr {
            if v.IsNil() {
                return
            }
            ptr := v.Pointer()
            if visited[ptr] {
                return // avoid infinite loops in cyclic structures
            }
            visited[ptr] = true
            v = v.Elem()
        }

        switch v.Kind() {
        case reflect.Struct:
            for i := 0; i < v.NumField(); i++ {
                field := v.Field(i)
                fieldType := v.Type().Field(i)

                // Recurse into nested values first
                walk(field)

                // Redact if this looks like a secret/password field
                if field.Kind() == reflect.String && field.CanSet() {
                    lname := strings.ToLower(fieldType.Name)
                    if strings.Contains(lname, "secret") || strings.Contains(lname, "password") {
                        field.SetString("******")
                    }
                }
            }
        case reflect.Slice, reflect.Array:
            for i := 0; i < v.Len(); i++ {
                walk(v.Index(i))
            }
        case reflect.Map:
            for _, key := range v.MapKeys() {
                walk(v.MapIndex(key))
            }
        }
    }

    walk(reflect.ValueOf(target))
}

