// constantTimeEquals compares two strings in constant time to avoid timing attacks.
// It does not require importing crypto/subtle, thereby keeping the original import list intact.
func constantTimeEquals(a, b string) bool {
    if len(a) != len(b) {
        return false
    }
    var diff byte
    for i := 0; i < len(a); i++ {
        diff |= a[i] ^ b[i]
    }
    return diff == 0
}

