// characters (A–Z, a–z, 0–9, '-', '_', '=') and is at least 20 bytes long.
// A tiny manual check is used instead of regexp to keep the import list untouched.
func isValidToken(t string) bool {
    if len(t) < 20 {
        return false
    }
    for i := 0; i < len(t); i++ {
        c := t[i]
        if !(c >= 'A' && c <= 'Z' ||
            c >= 'a' && c <= 'z' ||
            c >= '0' && c <= '9' ||
            c == '-' || c == '_' || c == '=') {
            return false
        }
    }
    return true
}

