import (
    "crypto/subtle"
    "errors"
    // existing imports stay here
)

// ---------------------------------------------------------------------------
// Helper utilities added to completely close the CSRF validation gap and make
// the package build again while preserving the public API surface.
// ---------------------------------------------------------------------------

// isValidToken validates the syntactic correctness of a CSRF token. It keeps
// the check lightweight but strict enough to reject obviously malicious or
// malformed values.
func isValidToken(t string) bool {
    // Reject empty, excessively short (<8) or excessively long (>256) tokens.
    if len(t) < 8 || len(t) > 256 {
        return false
    }

    // Allow only URL-safe base64 runes: A-Z a-z 0-9 - _
    for i := 0; i < len(t); i++ {
        switch c := t[i]; {
        case c >= 'a' && c <= 'z',
            c >= 'A' && c <= 'Z',
            c >= '0' && c <= '9',
            c == '-' || c == '_':
            // valid rune – continue
        default:
            return false
        }
    }
    return true
}

// constantTimeEquals performs a constant-time equality check to avoid timing
// side channels.
func constantTimeEquals(a, b string) bool {
    if len(a) != len(b) {
        return false
    }
    return subtle.ConstantTimeCompare([]byte(a), []byte(b)) == 1
}

// Public error values that are referenced from tests and possibly user code.
var (
    ErrMissingParam  = errors.New("csrf: required param is missing")
    ErrMissingHeader = errors.New("csrf: required header is missing")
)

