function buildURL (source, reqBase) {
  const dest = new URL(source, reqBase)

  // If a base is specified, additional security checks are required
  if (reqBase) {
    const base = new URL(reqBase)

    // 1. The origin (protocol + host + port) must stay the same
    if (dest.origin !== base.origin) {
      throw new Error('source must be a relative path string')
    }

    // 2. Ensure the resolved path stays within the base path "jail"
    //    a) Normalise the base path to always end with a slash so that
    //       subtree checks work reliably.
    let basePathWithSlash = base.pathname.endsWith('/') ? base.pathname : base.pathname + '/'

    const destPath = dest.pathname

    const isExactBasePath = destPath === base.pathname
    const isWithinBasePath = destPath.startsWith(basePathWithSlash)

    if (!(isExactBasePath || isWithinBasePath)) {
      throw new Error('source must stay within base path')
    }
  }

  return dest
}

