package common

import (
    "fmt"
    "strings"
    "time"
)

// -----------------------------------------------------------------------------
// NEW: EventManager allow-list support
// -----------------------------------------------------------------------------
// EventManagerConfig represents the event-manager specific configuration. The
// only field we currently need for hardening is the allow-list of executables
// that administrators are permitted to configure from the UI/API.
// If the slice is empty, *all* external command execution is disabled.
type EventManagerConfig struct {
    // AllowedCommands is the allow-list of absolute or relative paths to
    // executables that can be invoked.
    AllowedCommands []string `json:"allowed_commands" yaml:"allowed_commands"`
}

// Configuration is the global runtime configuration structure.  We add the
// EventManager field at the end so that the existing binary layout remains
// untouched for users that might serialise this struct.
type Configuration struct {
    // ... existing fields are intentionally left out for brevity ...

    // EventManager holds the configuration that is relevant for the
    // event-manager subsystem – most importantly the external command
    // allow-list introduced to mitigate CVE-2024-52309.
    EventManager EventManagerConfig `json:"event_manager" yaml:"event_manager"`
}

// -----------------------------------------------------------------------------
// Initialize – hardened against arbitrary external command execution
// -----------------------------------------------------------------------------
func Initialize(c Configuration, isShared int) error {
    isShuttingDown.Store(false)
    util.SetUmask(c.Umask)
    version.SetConfig(c.ServerVersion)
    dataprovider.SetTZ(c.TZ)
    Config = c

    // De-duplicate string slices ------------------------------------------------
    Config.Actions.ExecuteOn = util.RemoveDuplicates(Config.Actions.ExecuteOn, true)
    Config.Actions.ExecuteSync = util.RemoveDuplicates(Config.Actions.ExecuteSync, true)
    Config.ProxyAllowed = util.RemoveDuplicates(Config.ProxyAllowed, true)

    /* --------------------------------------------------------------------------
       External command hardening – validate against the EventManager allow-list
       -------------------------------------------------------------------------- */
    {
        allowedCmds := Config.EventManager.AllowedCommands // user-defined allow-list

        // helper: is a binary allowed?
        isAllowed := func(exec string) bool {
            for _, a := range allowedCmds {
                if a == exec {
                    return true
                }
            }
            return false
        }

        // helper: validate an entire slice of command lines
        validateCmds := func(cmds []string) error {
            for _, raw := range cmds {
                trimmed := strings.TrimSpace(raw)
                if trimmed == "" {
                    return fmt.Errorf("invalid empty command entry in configuration")
                }

                // everything up to the first space / tab is considered the executable
                exec := trimmed
                for i, r := range trimmed {
                    if r == ' ' || r == '\t' {
                        exec = trimmed[:i]
                        break
                    }
                }

                if !isAllowed(exec) {
                    return fmt.Errorf("command %q is not in the allow-list", exec)
                }
            }
            return nil
        }

        // if the allow-list is empty, external execution is disabled
        if len(allowedCmds) == 0 {
            if len(Config.Actions.ExecuteOn) > 0 || len(Config.Actions.ExecuteSync) > 0 {
                return fmt.Errorf("external command execution is disabled: no allow-list configured")
            }
        } else {
            if err := validateCmds(Config.Actions.ExecuteOn); err != nil {
                return err
            }
            if err := validateCmds(Config.Actions.ExecuteSync); err != nil {
                return err
            }
        }
    }

    // ---------------------------------------------------------------------------
    // original initialisation logic – untouched
    // ---------------------------------------------------------------------------
    Config.idleLoginTimeout = 2 * time.Minute
    Config.idleTimeoutAsDuration = time.Duration(Config.IdleTimeout) * time.Minute
    startPeriodicChecks(periodicTimeoutCheckInterval, isShared)
    Config.defender = nil
    Config.allowList = nil
    Config.rateLimitersList = nil
    rateLimiters = make(map[string][]*rateLimiter)
    for _, rlCfg := range c.RateLimitersConfig {
        if rlCfg.isEnabled() {
            if err := rlCfg.validate(); err != nil {
                return fmt.Errorf("rate limiters initialization error: %w", err)
            }
            rateLimiter := rlCfg.getLimiter()
            for _, protocol := range rlCfg.Protocols {
                rateLimiters[protocol] = append(rateLimiters[protocol], rateLimiter)
            }
        }
    }
    if len(rateLimiters) > 0 {
        rateLimitersList, err := dataprovider.NewIPList(dataprovider.IPListTypeRateLimiterSafeList)
        if err != nil {
            return fmt.Errorf("unable to initialize ratelimiters list: %w", err)
        }
        Config.rateLimitersList = rateLimitersList
    }
    if c.DefenderConfig.Enabled {
        if !slices.Contains(supportedDefenderDrivers, c.DefenderConfig.Driver) {
            return fmt.Errorf("unsupported defender driver %q", c.DefenderConfig.Driver)
        }
        var defender Defender
        var err error
        switch c.DefenderConfig.Driver {
        case DefenderDriverProvider:
            defender, err = newDBDefender(&c.DefenderConfig)
        default:
            defender, err = newInMemoryDefender(&c.DefenderConfig)
        }
        if err != nil {
            return fmt.Errorf("defender initialization error: %v", err)
        }
        logger.Info(logSender, "", "defender initialized with config %+v", c.DefenderConfig)
        Config.defender = defender
    }
    if c.AllowListStatus > 0 {
        allowList, err := dataprovider.NewIPList(dataprovider.IPListTypeAllowList)
        if err != nil {
            return fmt.Errorf("unable to initialize the allow list: %w", err)
        }
        logger.Info(logSender, "", "allow list initialized")
        Config.allowList = allowList
    }
    if err := c.initializeProxyProtocol(); err != nil {
        return err
    }
    vfs.SetTempPath(c.TempPath)
    dataprovider.SetTempPath(c.TempPath)
    vfs.SetAllowSelfConnections(c.AllowSelfConnections)
    vfs.SetRenameMode(c.RenameMode)
    vfs.SetReadMetadataMode(c.Metadata.Read)
    vfs.SetResumeMaxSize(c.ResumeMaxSize)
    vfs.SetUploadMode(c.UploadMode)
    dataprovider.SetAllowSelfConnections(c.AllowSelfConnections)
    transfersChecker = getTransfersChecker(isShared)
    return nil
}

