  // Ensure we have an options object
  if (!options || typeof options !== 'object') {
    options = {};
  }

  // ---------------------------------------------------------------------------
  // SECURITY: Reject non-string inputs early to avoid unexpected behaviour.
  // ---------------------------------------------------------------------------
  if (typeof str !== 'string') {
    return;
  }

  str = str.trim();

  // S4.1.1 Trailing semi-colons are not part of the specification.
  var semiColonCheck = TRAILING_SEMICOLON.exec(str);
  if (semiColonCheck) {
    str = str.slice(0, semiColonCheck.index);
  }

  // ---------------------------------------------------------------------------
  // ReDoS-free parsing of the first "name=value" pair (CVE-2016-1000232 fix)
  // ---------------------------------------------------------------------------
  var firstSemi = str.indexOf(';');          // S5.2 step 1
  var pairPart  = (firstSemi === -1 ? str : str.substr(0, firstSemi));

  var eqIndex = pairPart.indexOf('=');       // Linear scan – no back-tracking
  if (eqIndex < 1) {                         // Must have at least 1 char for name
    return;                                  // Empty names are invalid
  }

  var name  = pairPart.slice(0, eqIndex).trim();
  var value = pairPart.slice(eqIndex + 1).trim();

  var c = new Cookie();
  c.key   = name;
  c.value = value;

  // Validate control characters (same rule as original implementation)
  if (CONTROL_CHARS.test(c.key) || CONTROL_CHARS.test(c.value)) {
    return;
  }

  // If there is no attributes section, return the cookie now.
  if (firstSemi === -1) {
    return c;
  }

  // ---------------------------------------------------------------------------
  // Parse attributes – keep original behaviour but skip empty tokens.
  // ---------------------------------------------------------------------------
  var unparsed = str.slice(firstSemi)            // start from first semicolon
                    .replace(/^\s*;\s*/, '')   // discard first semicolon
                    .trim();

  if (unparsed.length === 0) {
    return c;
  }

  var cookie_avs = unparsed.split(/\s*;\s*/);
  while (cookie_avs.length) {
    var av = cookie_avs.shift();

    // Skip completely empty attributes produced by ";;;" etc.
    if (!av) {
      continue;
    }

    var av_sep = av.indexOf('=');
    var av_key, av_value;

    if (av_sep === -1) {
      av_key   = av;
      av_value = null;
    } else {
      av_key   = av.substr(0, av_sep);
      av_value = av.substr(av_sep + 1);
    }

    av_key = av_key.trim().toLowerCase();

    // Skip attributes that end up with an empty key (e.g., stray semicolons)
    if (av_key.length === 0) {
      continue;
    }

    if (av_value) {
      av_value = av_value.trim();
    }

    switch (av_key) {
      case 'expires': // S5.2.1
        if (av_value) {
          var exp = parseDate(av_value);
          if (exp) {
            c.expires = exp;
          }
        }
        break;

      case 'max-age': // S5.2.2
        if (av_value && /^-?[0-9]+$/.test(av_value)) {
          var delta = parseInt(av_value, 10);
          c.setMaxAge(delta);
        }
        break;

      case 'domain': // S5.2.3
        if (av_value) {
          var domain = av_value.trim().replace(/^\./, '');
          if (domain) {
            c.domain = domain.toLowerCase();
          }
        }
        break;

      case 'path': // S5.2.4
        c.path = av_value && av_value[0] === '/' ? av_value : null;
        break;

      case 'secure': // S5.2.5
        c.secure = true;
        break;

      case 'httponly': // S5.2.6
        c.httpOnly = true;
        break;

      default:
        // Record non-standard extensions, but only if non-empty.
        if (av.length) {
