function parse(str, options) {
  // -------------------------------------------------------------------------
  // Ensure valid input types and default options object
  // -------------------------------------------------------------------------
  if (typeof str !== 'string') {
    return; // Maintain original contract: return undefined on bad input
  }
  if (!options || typeof options !== 'object') {
    options = {};
  }

  // Trim leading/trailing spaces – RFC6265 S4.1
  str = str.trim();

  // S4.1.1 – Trailing semi-colons are not part of the specification
  var semiColonCheck = TRAILING_SEMICOLON.exec(str);
  if (semiColonCheck) {
    str = str.slice(0, semiColonCheck.index);
  }

  // -------------------------------------------------------------------------
  // ReDoS-safe parsing of the first "name=value" pair (replaces COOKIE_PAIR)
  // -------------------------------------------------------------------------
  var firstSemi = str.indexOf(';');                 // S5.2 step 1
  var pairPart  = (firstSemi === -1 ? str : str.substr(0, firstSemi));

  // Locate the first "=" – must exist and cannot be at position 0
  var eqIndex = pairPart.indexOf('=');
  if (eqIndex < 1) {                                // Empty name is invalid
    return;                                         // Behave like original impl.
  }

  var name  = pairPart.slice(0, eqIndex).trim();
  var value = pairPart.slice(eqIndex + 1).trim();

  var c = new Cookie();
  c.key   = name;
  c.value = value;

  // Control-character check (same rule as original)
  if (CONTROL_CHARS.test(c.key) || CONTROL_CHARS.test(c.value)) {
    return;
  }

  // If there is no attributes section, we are done.
  if (firstSemi === -1) {
    return c;
  }

  // -------------------------------------------------------------------------
  // Parse attributes – logic remains identical to original implementation
  // -------------------------------------------------------------------------
  var unparsed = str.slice(firstSemi)          // start from first semicolon
                    .replace(/^\s*;\s*/, '') // discard first semicolon
                    .trim();

  if (unparsed.length === 0) {
    return c;
  }

  var cookie_avs = unparsed.split(/\s*;\s*/);
  while (cookie_avs.length) {
    var av = cookie_avs.shift();

    // Skip completely empty attributes produced by consecutive semicolons
    if (!av) {
      continue;
    }

    var av_sep = av.indexOf('=');
    var av_key, av_value;

    if (av_sep === -1) {
      av_key   = av;
      av_value = null;
    } else {
      av_key   = av.substr(0, av_sep);
      av_value = av.substr(av_sep + 1);
    }

    av_key = av_key.trim().toLowerCase();
    if (av_value) {
      av_value = av_value.trim();
    }

    switch (av_key) {
      case 'expires': // S5.2.1
        if (av_value) {
          var exp = parseDate(av_value);
          if (exp) {
            c.expires = exp;
          }
        }
        break;

      case 'max-age': // S5.2.2
        if (av_value && /^-?[0-9]+$/.test(av_value)) {
          var delta = parseInt(av_value, 10);
          c.setMaxAge(delta);
        }
        break;

      case 'domain': // S5.2.3
        if (av_value) {
          var domain = av_value.trim().replace(/^\./, '');
          if (domain) {
            c.domain = domain.toLowerCase();
          }
        }
        break;

      case 'path': // S5.2.4
        c.path = av_value && av_value[0] === '/' ? av_value : null;
        break;

      case 'secure': // S5.2.5
        c.secure = true;
        break;

      case 'httponly': // S5.2.6
        c.httpOnly = true;
        break;

      default:
        // Record non-standard extensions
        if (av.length) {
          c.extensions = c.extensions || [];
          c.extensions.push(av);
        }
        break;
    }
  }

  return c;
}

