export function handler (type, name, fn) {
  // Ensure a clean, prototype-less bucket for the given type
  if (!handlers[type] || Object.prototype.toString.call(handlers[type]) !== '[object Object]') {
    handlers[type] = Object.create(null)
  }

  const forbiddenKeys = ['__proto__', 'prototype', 'constructor']

  // Setter branch
