resolve: function resolve(hostname) {
        var output,
            nodeBinary = process.execPath,
            scriptPath = path.join(__dirname, "../scripts/dns-lookup-script"),
            child_process = require("child_process");

        /*
         * Basic hostname validation – only allow letters, numbers, dots, dashes
         * and underscores. Reject anything else to reduce misuse. This is an
         * additional safeguard; main protection comes from execFileSync (no
         * shell).
         */
        if (typeof hostname !== "string" || !hostname.length || /[^a-zA-Z0-9._-]/.test(hostname)) {
            debug('hostname', "invalid hostname " + hostname);
            return null;
        }

        try {
            // Execute the lookup script without spawning a shell to avoid command injection
            output = child_process.execFileSync(
                nodeBinary,
                [scriptPath, hostname],
                { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }
            ).trim();

            if (output && net.isIP(output)) {
                return output;
            }
        } catch (e) {
            // execFileSync throws on non-zero exit codes or other failures
            debug('hostname', "fail to resolve hostname " + hostname + " : " + e.message);
        }

        return null;
    }

