module.execute = function(arrParams) {
    return new Promise(function(resolve, reject) {
        const childProcess = require('child_process');
        const path = require('path');
        var jarPath = path.join(__dirname, 'jar', 'key-sender.jar');

        // Ensure the incoming parameter is an array
        if (!Array.isArray(arrParams)) {
            return reject(new TypeError('arrParams must be an array'));
        }

        // Build argument list safely without invoking a shell
        var args = ['-jar', jarPath];

        arrParams.forEach(function(param) {
            if (param !== undefined && param !== null) {
                args.push(String(param));
            }
        });

        // Include any additional CLI options that the library may require
        var extraOptions = module.getCommandLineOptions();
        if (typeof extraOptions === 'string' && extraOptions.trim().length > 0) {
            args = args.concat(extraOptions.trim().split(/\s+/));
        }

        // Execute the command without a shell to prevent injection
        return childProcess.execFile('java', args, {}, function(error, stdout, stderr) {
            if (error == null) {
                resolve(stdout, stderr);
            } else {
                reject(error, stdout, stderr);
            }
        });
    });
};

