function template(literal, data) {
  // Validate input types to avoid unexpected errors
  if (typeof literal !== 'string' || !literal) {
    return '';
  }

  // Replace `${key}` placeholders with the corresponding value from `data` safely
  return literal.replace(/\$\{([^}]+)\}/g, function (match, expression) {
    var keyPath = (expression || '').trim();

    // Only allow simple identifiers and dot-notation (e.g., user.name)
    if (!/^[A-Za-z_$][\w$]*(\.[A-Za-z_$][\w$]*)*$/.test(keyPath)) {
      return '';
    }

    // Prevent prototype pollution / access to Object internals
    var unsafeKeys = ['__proto__', 'prototype', 'constructor'];
    var segments = keyPath.split('.');
    for (var i = 0; i < segments.length; i++) {
      if (unsafeKeys.indexOf(segments[i]) !== -1) {
        return '';
      }
    }

    var value = data;
    for (i = 0; i < segments.length; i++) {
      if (value == null) {
        return '';
      }
      if (Object.prototype.hasOwnProperty.call(value, segments[i])) {
        value = value[segments[i]];
      } else {
        return '';
      }
    }

    // Convert the returned value to string to mimic template literal behaviour
    return String(value);
  });
}

