var main = function(req, res) {
        var reqUrl = req.url;
        // 记录请求信息
        logger.http(req, res);

        // 使用 url 解析模块获取 url 中的路径名
        var rawPathName = url.parse(reqUrl).pathname || "/";

        /*
         * 安全解码：
         *  1. 多次解码，防止双重/多重编码绕过
         *  2. 失败时回退到根目录，避免异常导致的路径穿越
         */
        var safeDecode = function(component) {
            try {
                var decoded = component;
                var previous = "";
                var maxLoop  = 5; // 最多解码 5 次，足够阻止多重编码
                while (decoded !== previous && maxLoop-- > 0) {
                    previous = decoded;
                    decoded  = decodeURIComponent(decoded);
                }
                return decoded;
            } catch (e) {
                return "/"; // 解码失败时退回根目录
            }
        };

        rawPathName = safeDecode(rawPathName);

        // 统一分隔符，处理 Windows 风格的 "\\"
        rawPathName = rawPathName.replace(/\\+/g, "/");

        var pathName = rawPathName;

        // 补全文件路径
        if (path.extname(pathName) === "") {
            if (!/\/$/.test(pathName)) {
                pathName += "/";
            }
            pathName += argvs.getDefault();
        }

        // 基准目录（绝对路径）
        var basePath = path.resolve(argvs.getPath());

        // 组合并规范化路径
        var filePath = path.resolve(basePath, "." + pathName);

        /*
         * 检查解析后的路径是否逃逸出基准目录：
         *   - 通过 path.relative 来判断
         *   - 若相对路径以 ".." 开头或为绝对路径则说明发生了目录穿越
         */
        var relative = path.relative(basePath, filePath);
        if (relative.startsWith("..") || path.isAbsolute(relative) || relative === "") {
            res.writeHead(403, { "Content-Type": "text/html" });
            res.end("<h1>403 Forbidden</h1>");
            logger.warn("Path traversal attempt: [" + filePath + "]");
            return;
        }

        // 判断文件是否存在
        fs.exists(filePath, function(exists) {
            try {
                if (exists) {
                    // 在返回头中写入内容类型
                    res.writeHead(200, {
                        "Content-Type": mime.lookup(filePath)
                    });

                    // 创建只读流用于返回
                    var stream = fs.createReadStream(filePath, {
                        flags: "r",
                        encoding: null
                    });

                    // 指定如果流读取错误,返回404错误
                    stream.on("error", function() {
                        res.writeHead(404);
                        res.end("<h1>500 the file [path=" + filePath + "] Read Error!</h1>");
                    });
                    // 连接文件流和 http 返回流的管道,用于返回实际 Web 内容
                    stream.pipe(res);
                } else {
                    // 返回404错误
                    res.writeHead(404, {
                        "Content-Type": "text/html"
                    });
                    res.end("<h1>404 Not Found file [path=" + filePath + "]</h1>");
                }
            } catch (e) {
                logger.error("read file from [" + filePath + "] error!");
            }
        });
    }

