    if (!require('path').isAbsolute(path) || unsafePattern.test(path)) {
        if (this.settings.debug_mode) console.log(`${this.debug_label}: Invalid path for ${scanner} binary.`);
        return false;
    }

    // Promisified execFile (no shell involved)
    const execFile = require('util').promisify(require('child_process').execFile);
