var path = require('path');

var cleanUrl = function(url) {
    // Ensure we are working with a string
    if (typeof url !== 'string') {
        return '';
    }

    // Decode once – wrap to avoid exceptions on malformed sequences
    try {
        url = decodeURIComponent(url);
    } catch (e) {
        // Retain original string if decoding fails
    }

    /*
     * Normalise the path to collapse any '../' or './' tokens.
     * Prepend a leading slash so path.posix treats it as absolute,
     * then strip that slash afterwards to keep the path relative.
     */
    url = path.posix.normalize('/' + url).replace(/^\/+/, '');

    // Defence-in-depth: strip remaining leading "../" segments (if any)
    while (url.startsWith('..' + path.posix.sep)) {
        url = url.slice(3);
    }

    return url;
};

