module.exports = function(app, cb) {
  const child_process = require('child_process');

  // Validate the Heroku app name to prevent command injection
  // Heroku app names may contain lowercase letters, numbers, and hyphens
  if (typeof app !== 'string' || !/^[a-zA-Z0-9-]+$/.test(app)) {
    return cb(new Error('Invalid Heroku app name'));
  }

  // Use execFile to run the command without a shell, eliminating injection risk
  child_process.execFile(
    'heroku',
    ['config', '--app', app],
    function(err, stdout) {
      if (err) return cb(err);
      var config = {};
      var lines = stdout.split('\n');
      // The first line is usually a header like "=== app Config Vars ==="
      lines.shift();
      lines.forEach(function(line) {
        if (!line.trim()) return;
        var parts = line.split(': ');
        if (!parts[1]) {
          console.log('could not parse', line);
        } else {
          config[parts[0].trim()] = parts[1].trim();
        }
      });
      cb(null, config);
    }
  );
};

