import (
    "fmt"
    "log"
    "os/exec"
    "strings"
)

// PDFHasImage returns true when the first 5 pages of the PDF contain
// no embedded fonts, which is interpreted as the PDF consisting only
// of images.
func PDFHasImage(path string) bool {
    // Execute pdffonts directly without invoking a shell to avoid
    // command-injection vulnerabilities.
    out, err := exec.Command("pdffonts", "-l", "5", path).Output()
    if err != nil {
        log.Println(err)
        return false
    }

    // pdffonts prints two header lines followed by font entries.
    lines := strings.Split(string(out), "\n")
    if len(lines) <= 2 { // only headers present → no fonts detected
        return true
    }

    // Check remaining lines for any non-empty content (i.e., fonts).
    for _, l := range lines[2:] {
        if strings.TrimSpace(l) != "" {
            return false // font detected → not an image-only PDF
        }
    }
    return true // no fonts detected → image-only PDF
}

