func PDFHasImage(path string) bool {
    // Execute pdffonts safely without spawning a shell to avoid command-injection.
    // We mimic the shell pipeline "pdffonts -l 5 <file> | tail -n +3 | cut -d' ' -f1 | sort | uniq"
    // directly in Go so that behaviour stays the same while removing the vulnerability.

    out, err := exec.Command("pdffonts", "-l", "5", path).Output()
    if err != nil {
        log.Println(err)
        return false
    }

    // Split output into lines. The first two lines are headers that should be skipped.
    lines := strings.Split(string(out), "\n")
    if len(lines) <= 2 {
        // Only headers present → no fonts detected → image-only PDF
        return true
    }

    // Collect unique, non-empty font names from the remaining lines (starting at index 2).
    fonts := make(map[string]struct{})
    for _, l := range lines[2:] {
        name := strings.Fields(l) // split on any whitespace and take first column if present
        if len(name) == 0 {
            continue
        }
        fonts[name[0]] = struct{}{}
    }

    // If the set is empty, there were no fonts.
    return len(fonts) == 0
}

