    if (typeof output !== "string" || output.trim() === "") {
      return reject(new Error("Invalid output filename"));
    }
    const baseOutput = path.basename(output);
    const validName = /^[A-Za-z0-9_\-]+$/;
    if (!validName.test(baseOutput)) {
      return reject(new Error("Invalid characters in output filename"));
    }

    // Always append .mp4 (same behaviour as original implementation)
    const finalOutputName = `${baseOutput}.mp4`;
    const outputPath = path.resolve(path.dirname(resolvedInput), finalOutputName);

    const ffmpegArgs = [
      "-hide_banner",
      "-loglevel", "quiet",
      "-ss", `${startNum}`,
      "-i", resolvedInput,
      "-t", `${durationNum}`,
      "-c", "copy",
      "-y", outputPath,
    ];

    const ffmpegProcess = spawn("ffmpeg", ffmpegArgs, { stdio: "ignore" });

    ffmpegProcess.on("error", (error) => {
      reject(error);
    });

    ffmpegProcess.on("close", (code) => {
      if (code !== 0) {
        return reject(new Error(`ffmpeg exited with code ${code}`));
      }
      // Preserve original return-value semantics
