function parseUrl(url, normalize = false) {
    if (typeof url !== "string" || !url.trim()) {
        throw new Error("Invalid url.");
    }

    // Optional "normalize-url" step kept from the original implementation
    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = { stripHash: false };
        }
        url = normalizeUrl(url, normalize);
    }

    const parsed = parsePath(url);

    /* ------------------------------------------------------------------
     * HANDLING SCP-STYLE (git@host:repo)  URLs
     * ------------------------------------------------------------------
     * parsePath() recognises them as local files (protocol "file").
     * We detect the pattern and rewrite the affected fields so that the
     * resulting object matches the behaviour expected by the library’s
     * public API and unit-tests (protocol "ssh", correct user/resource). */
    const scpLikeMatch = /^([^@]+)@([^:]+):(.+)$/.exec(url);
    if (parsed && parsed.protocol === "file" && scpLikeMatch) {
        parsed.protocols = ["ssh"];
        parsed.protocol  = "ssh";
