@classmethod
def find_profile_dir_by_name(cls, ipython_dir, name=u'default', config=None):
    """Find an existing profile dir by profile name, return its ProfileDir.

    This searches through a sequence of paths for a profile dir.  If it
    is not found, a :class:`ProfileDirError` exception will be raised.

    The search path algorithm is:
    1. ``os.getcwd()``
    2. ``ipython_dir``

    Security hardening: a candidate directory will be accepted only if it
    is owned by the current user and is not writable by group or others.
    """

    def _is_profile_dir_secure(path):
        """Return True if *path* is owned by the current user and not writable
        by group/others.  On any failure (e.g., path disappearing), it
        returns False so the directory is ignored.
        """
        try:
            st = os.stat(path)
        except OSError:
            return False

        # Must be owned by the current user.
        if st.st_uid != os.getuid():
            return False
        # Must not be writable by group or others.
        if st.st_mode & 0o022:
            return False
        return True

    dirname = u'profile_' + name
    paths = [os.getcwd(), ipython_dir]
    for p in paths:
        profile_dir = os.path.join(p, dirname)
        if os.path.isdir(profile_dir) and _is_profile_dir_secure(profile_dir):
            return cls(location=profile_dir, config=config)
    else:
        raise ProfileDirError('Profile directory not found in paths: %s' % dirname)

