const path = require('path');

/**
 * Secure replacement for the previous df wrapper.
 *
 * @param {Object|Function}  options  Options hash or callback when omitted
 * @param {Function}         callback Node-style callback (err, entries)
 */
function vul_js_13(options, callback) {
    /* ------------------------------------------------------------------
     * 0.  Handle optional parameters exactly like the original signature
     * ------------------------------------------------------------------ */
    if (typeof options === 'function') {
        callback = options;
        options = Object.create(null);
    }

    // Basic contract checks
    if (typeof callback !== 'function') {
        throw new TypeError('Callback must be a function');
    }

    options = options || Object.create(null);

    /* ------------------------------------------------------------------
     * 1.  Build a *safe* argv array for execFile – never a shell string
     * ------------------------------------------------------------------ */
    const executable = 'df';
    const args = ['-kP']; // keep original default flags

    // If a specific file/path was requested, validate strictly
    if (options.file !== undefined) {
        if (typeof options.file !== 'string' || !options.file.length) {
            return callback(new TypeError('options.file must be a non-empty string'));
        }

