        const resolvedPath = path.resolve(options.file);

        // “--” ensures any subsequent token is treated as an operand, not an option
        args.push('--', resolvedPath);
    }

    /* ------------------------------------------------------------------
     * 2.  Execute safely using execFile (no shell)
     * ------------------------------------------------------------------ */
    child_process.execFile(
        executable,
        args,
        { maxBuffer: 1024 * 1024, shell: false },
        function (err, stdout, stderr) {
            if (err) {
                callback(err);
                return;
            }

            if (stderr && stderr.length) {
                callback(new Error(stderr.toString()));
                return;
            }

            // Preserve the original behaviour – delegate to existing parse()
            try {
                const entries = parse(stdout, options);
                callback(null, entries);
            } catch (parseErr) {
                callback(parseErr);
            }
        }
