function cpOptsInData(data, opts) {
  // Options that user data must *never* be allowed to override.  Allowing
  // these can lead to directory-traversal, remote-code-execution or other
  // serious issues.
  var UNSAFE_OPTS = [
    'root',
    'views',
    'context',
    'outputFunctionName'
  ];

  _OPTS.forEach(function (p) {
    // Skip if property not supplied by user
    if (!Object.prototype.hasOwnProperty.call(data, p)) {
      return;
    }

    // Skip any option considered unsafe
    if (UNSAFE_OPTS.indexOf(p) !== -1) {
      return;
    }

    var v = data[p];

    // Only primitive types are allowed – this blocks prototype-pollution and
    // excessive memory usage caused by complex objects.
    if (v === null || ['string', 'boolean', 'number'].indexOf(typeof v) === -1) {
      return;
    }

    // Basic validation for string values
    if (typeof v === 'string') {
      // Reject extremely long strings that may trigger a DoS.
      if (v.length > 255) {
        return;
      }
      // Reject strings containing NUL bytes which can truncate paths on some FS.
      if (v.indexOf('\u0000') !== -1) {
        return;
      }
    }

    // Prevent the downstream "cache option requires a filename" error.
    if (p === 'cache' && v === true) {
      var filename = typeof data.filename === 'string' ? data.filename : opts.filename;
      if (!filename || filename.length === 0) {
        // Ignore an unsafe cache flag rather than letting it crash execution.
        return;
      }
    }

    // All checks passed – copy the option.
    opts[p] = v;
  });
}

