const parseUrl = (url, normalize = false) => {

    // Constants
    const GIT_RE = /(^(git@|http(s)?:\/\/)([\w\.\-@]+)(\/|:))(([\~,\.\w,\-,\_,\/]+)(.git){0,1}((\/){0,1}))/;

    // ---- [SECURITY PATCH BEGIN] ----
    // 1. Basic type & emptiness check (kept from original implementation)
    if (typeof url !== "string" || !url.trim()) {
        const err = new Error("Invalid url.")
        err.subject_url = url
        throw err
    }

    // 2. Trim to remove leading/trailing whitespace
    url = url.trim()

    // 3. Reject any URL that contains ASCII control characters or inner-string whitespace (spaces, tabs, CR, LF)
    //    These characters can be abused for request-smuggling / SSRF bypass tricks.
    const INVALID_CHARS_RE = /[\u0000-\u001F\u007F\s]/
    if (INVALID_CHARS_RE.test(url)) {
        const err = new Error("Invalid url. The value contains illegal characters.")
        err.subject_url = url
        throw err
    }
